rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "The client must not send records with a ContentType of 'application_data' prior to sending the Finished message, unless explicitly allowed in Section 2.3 of the TLS 1.3 specification."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must verify that it does not receive records with a ContentType of 'application_data' before the Finished message. If such records are received in violation of this rule, the server must terminate the connection with an appropriate alert, such as 'unexpected_message'."
        }
    }
}

strategy:
{
    "rule_violation": "The client sends records with a ContentType of 'application_data' before sending the Finished message, violating the sequence rules defined in the TLS 1.3 specification.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLS record with ContentType set to 'application_data' immediately after the initial ClientHello message, without completing the handshake.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLS record with ContentType set to 'application_data' before sending the Finished message after the ServerHello message has been sent and before the client Finished message.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send multiple TLS records with ContentType set to 'application_data' during the handshake, specifically before any Finished message.",
            "expected_behavior": "Alert"
        }
    ]
}

