rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extension.type",
        "construction_rule": {
            "role": "client",
            "content": "When using the Pre-Shared Key (PSK) Extension in TLS 1.3, the client may use it alone without key exchange mode extensions. However, this results in the application data losing forward secrecy."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello that includes the Pre-Shared Key (PSK) Extension without any key exchange mode extensions, the server must process the extension and proceed with the handshake. However, the server must recognize that forward secrecy is lost for application data exchanged during the session."
        }
    }
}

strategy:
{
    "rule_violation": "The client uses the Pre-Shared Key (PSK) Extension in TLS 1.3 without including any key exchange mode extensions, leading to a loss of forward secrecy.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message with only the Pre-Shared Key (PSK) Extension included, without any key exchange mode extensions.",
            "expected_behavior": "ServerHello"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message with a malformed Pre-Shared Key (PSK) Extension, omitting key exchange mode extensions.",
            "expected_behavior": "Alert"
        }
    ]
}

