rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "server",
            "content": "The server MUST omit the Certificate message if it is not authenticating with a certificate."
        },
        "processing_rule": {
            "role": "client",
            "content": "The client MUST omit the Certificate message if the server did not send a CertificateRequest, indicating that client certificate authentication is not required."
        }
    }
}

strategy:
{
    "rule_violation": "The server sends a Certificate message even though it is not authenticating with a certificate, violating the omission requirement for non-certificate authentication.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Have the server send a Certificate message in the handshake process even though it is not set up to authenticate using a certificate.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a mock server message chain that includes a Certificate message without prior setup for certificate-based authentication.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Introduce a configuration on the server that forces sending a Certificate message despite not requiring a certificate for authentication.",
            "expected_behavior": "Alert"
        }
    ]
}

