        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "server",
            "content": "When sending Application Data in TLS 1.3, the server may send data prior to receiving the client's Authentication messages, but must be aware that it is being sent to an unauthenticated peer."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving Application Data before Authentication messages, the client should handle this data with awareness that it originates from an unauthenticated peer and should process it accordingly."
        }
    }
}

