rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When sending a ClientHello, the client MUST include the 'signature_algorithms' extension to indicate the signature algorithms it can accept."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST process the 'signature_algorithms' extension to determine the signature algorithms supported by the client. If unsupported algorithms are proposed, the server may choose to terminate the handshake with an appropriate alert."
        }
    }
}

