rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.color",
        "construction_rule": {
            "role": "client",
            "content": "Fields of enumerated type, such as 'tls.handshake.color', MUST occupy as much space in the byte stream as required by the maximal defined ordinal value. The 'Color' field MUST always use one byte in the byte stream."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving message fields of enumerated type, such as 'tls.handshake.color', the server MUST interpret the size of the field according to the maximal defined ordinal value (one byte for the 'Color' field). If the size of the field does not match this requirement, the message MUST be rejected as malformed."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to encode the 'tls.handshake.color' field using the required byte size (one byte), violating the field size requirement.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.color",
            "description": "Send a message with the 'tls.handshake.color' field encoded using two bytes instead of one byte.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.color",
            "description": "Send a message with the 'tls.handshake.color' field encoded using zero bytes (omitting the field entirely).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.color",
            "description": "Send a message with the 'tls.handshake.color' field encoded incorrectly using three bytes.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.color",
            "description": "Send a message with the 'tls.handshake.color' field set to a value larger than one byte, such as 0x01FF.",
            "expected_behavior": "Alert"
        }
    ]
}

