        },
        "processing_rule": {
            "role": "server",
            "content": "If the server selects an (EC)DHE group and the client's 'key_share' extension in the initial ClientHello does not offer a compatible group, the server MUST respond with a HelloRetryRequest message in compliance with Section 4.1.4 of the TLS 1.3 specification."
        }
    }
}

