rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client/server",
            "content": "For TLS 1.3 handshake, the implementation MUST construct handshake messages to comply with the protocol and provide all necessary information to avoid triggering handshake failure or other protocol errors. An alert message MAY be included before connection termination if needed."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "Upon encountering a handshake failure or other protocol error, the implementation MUST terminate the connection immediately. An alert message SHOULD be sent prior to termination, as specified in Section 6 of the TLS 1.3 specification."
        }
    }
}

