rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "If the client is authenticating via a certificate, the CertificateVerify message must be constructed as a signature over the entire handshake using the client's private key corresponding to the public key in the Certificate message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a CertificateVerify message, the server must verify that it is a valid signature over the entire handshake using the public key provided in the Certificate message. If the signature is invalid or if the client is not authenticating via a certificate, this message is omitted."
        }
    }
}

