            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with a corrupted or incorrect signature.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Omit sending the CertificateVerify message when client authentication via a certificate is required.",
            "expected_behavior": "Alert"
        }
    ]
}

