rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "Key Share extension",
        "construction_rule": {
            "role": "client",
            "content": "When a client offers resumption via a PSK in TLS 1.3, the client SHOULD include a 'key_share' extension in the ClientHello message to enable the server to decline resumption and initiate a full handshake if needed."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello with a PSK offering resumption and a 'key_share' extension, the server MUST evaluate the 'key_share' extension to decide whether to proceed with resumption or perform a full handshake. If the 'key_share' extension is absent or malfunctions, the server should continue with resumption if possible, or initiate a full handshake."
        }
    }
}

