rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "When sending records, the client must ensure that 0-RTT data is encrypted using keys derived for 0-RTT and clearly distinguishable from 1-RTT data, which uses different encryption keys. This distinction must be maintained to prevent confusion between 0-RTT and 1-RTT data."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a record, the server must verify that 0-RTT data is properly separated from 1-RTT data by identifying the correct encryption keys used for each type. If an attacker tries to make 0-RTT data appear as 1-RTT data, the server must detect this discrepancy and handle it appropriately, ensuring no data is interpreted incorrectly due to key mismanagement."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly separate 0-RTT data from 1-RTT data, causing encryption keys to be mixed and indistinguishable between 0-RTT and 1-RTT.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a record purporting to be 0-RTT data using 1-RTT encryption keys, thereby blurring the distinction between 0-RTT and 1-RTT.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a mix of 0-RTT data and 1-RTT data within a single record without maintaining separate encryption for each, using a single encryption key.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send 0-RTT data encrypted with completely undefined or incorrect keys to simulate key mismanagement or malicious alteration.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Craft a record marked as 1-RTT which includes only 0-RTT data, effectively making 0-RTT data appear as 1-RTT data intentionally.",
            "expected_behavior": "Alert"
        }
    ]
}

