        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello message during PSK key establishment, the client must check the presence of the 'pre_shared_key' extension. The client must verify that the extension indicates one of the PSKs it offered. If any inconsistency is found, the client should terminate the handshake with an 'illegal_parameter' alert."
        }
    }
}

