rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Finished message in TLS 1.3, the client must ensure it is a MAC over the entire handshake, providing key confirmation, binding the client's identity to the exchanged keys. In PSK mode, it must authenticate the handshake as well."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a Finished message, the server must verify that it is a MAC over the entire handshake, confirming keys and binding the client's identity to the keys. In PSK mode, the server must check it for handshake authentication. If these validations fail, the server must abort the handshake."
        }
    }
}

