rule:
{
"structured_rule": {
"protocol": "TLS 1.3",
"message": "No Extension",
"field": "tls.handshake.type",
"construction_rule": {
"role": "client",
"content": "The client must send ClientHello only at the beginning of the handshake process when initiating a TLS 1.3 connection."
},
"processing_rule": {
"role": "server",
"content": "If the server, having negotiated TLS 1.3, receives a ClientHello at any other time, it must terminate the connection with an 'unexpected_message' alert, as TLS 1.3 forbids renegotiation."
}
}
}

strategy:
{
    "rule_violation": "The client sends a ClientHello message after the initial handshake process, violating the rule that ClientHello must only be sent at the beginning of the handshake in a TLS 1.3 connection.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message after the connection has been established and application data is being exchanged.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message following a successful handshake completion during re-keying attempts.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message after an explicit application-level renegotiation request.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message midway during an ongoing handshake initiated by the server.",
            "expected_behavior": "Alert"
        }
    ]
}

