rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extension.type",
        "construction_rule": {
            "role": "server",
            "content": "When the server successfully selects parameters and does not need a HelloRetryRequest, it must include the 'pre_shared_key' extension in the ServerHello to indicate the selected pre-shared key parameters."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the ServerHello, the client must check if the 'pre_shared_key' extension is included when no HelloRetryRequest is needed. If the extension is present, the client uses the indicated pre-shared key parameters."
        }
    }
}

