        "construction_rule": {
            "role": "client",
            "content": "When resending a ClientHello in response to a HelloRetryRequest, the client must include the 'cookie' extension if it was provided in the HelloRetryRequest."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello containing a 'cookie' extension, the server must verify the extension and ensure the cookie's validity before proceeding with the handshake. If the cookie is missing or invalid, the server should abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

