        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message with a Pre Shared Key Extension, the server must verify and support the use of (EC)DHE key exchange in conjunction with the shared key to ensure forward secrecy capabilities."
        }
    }
}

