rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_client_length",
        "construction_rule": {
            "role": "server",
            "content": "When the server performs (EC)DHE key establishment for forward secrecy, it MUST include the 'key_share' extension in its response. This extension MUST contain the server's selected group and corresponding key share."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the server's 'key_share' extension, the client MUST validate that it corresponds to a supported (EC)DHE group and includes a valid key share. If validation fails, the client MUST abort the handshake with an appropriate alert."
        }
    }
}

