rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.length",
        "construction_rule": {
            "role": "client",
            "content": "While encoding variable-length vectors in ClientHello or other handshake messages, the client MUST place the actual length of the vector as a number, preceding the vector's contents in the byte stream. The length value MUST occupy as many bytes as necessary to represent the vector's maximum specified length."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving variable-length vectors in handshake messages, the server MUST ensure that the actual length precedes the vector's contents and that this length is encoded as a number consuming as many bytes as necessary for the vector's maximum ceiling length. If the encoding does not meet these conditions, the server MUST terminate the connection with a 'decode_error' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client improperly encodes the length of variable-length vectors in ClientHello or other handshake messages, either by not preceding the vector with its length or by using an incorrect number of bytes for the length.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a ClientHello message with a vector whose length field is missing entirely, containing just the vector contents.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a ClientHello message with a vector length field that occupies fewer bytes than necessary for the maximum specified length, followed by the vector contents.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a ClientHello message with a vector length field that occupies more bytes than necessary for the maximum specified length, followed by the vector contents.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a ClientHello message with an incorrect length field value for a vector, which does not match the actual size of the vector contents.",
            "expected_behavior": "Alert"
        }
    ]
}

