rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
        "construction_rule": {
            "role": "client",
            "content": "When a 'pre_shared_key' extension is present, the client MUST update the 'obfuscated_ticket_age' by recomputing it according to the protocol specifications."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST verify that the 'obfuscated_ticket_age' in the 'pre_shared_key' extension is correctly computed. Additionally, the server MUST recompute the binder values and MAY remove any PSKs incompatible with the selected cipher suite."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly update and recompute the 'obfuscated_ticket_age' in the 'pre_shared_key' extension according to the protocol specifications.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
            "description": "Send a ClientHello message containing a 'pre_shared_key' extension with a static 'obfuscated_ticket_age' that has not been updated since the original ticket was issued.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
            "description": "Send a ClientHello message with 'obfuscated_ticket_age' set to zero in the 'pre_shared_key' extension, regardless of the actual ticket age.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
            "description": "Send a ClientHello message with 'obfuscated_ticket_age' in the 'pre_shared_key' extension set to an incorrect value that significantly deviates from the expected computation, such as double the expected ticket age.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
            "description": "Send a ClientHello message with a negative value for 'obfuscated_ticket_age' in the 'pre_shared_key' extension, which is not possible in the correct computation.",
            "expected_behavior": "Alert"
        }
    ]
}

