rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "server",
            "content": "In scenarios involving certificate-based client authentication, the server must construct the CertificateRequest message with the desired parameters for the client's certificate. This message should be omitted if client authentication is not required."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the CertificateRequest message during the TLS handshake, the client must process it as an indication of the server requiring client authentication. If the message is absent, the client concludes that authentication is not required by the server."
        }
    }
}

strategy:
{
    "rule_violation": "The server constructs the CertificateRequest message improperly by either omitting required parameters, including conflicting information, or sending it when client authentication is not required.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateRequest message without specifying any parameters for the client's certificate, leaving it empty.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateRequest message that includes conflicting parameters, such as specifying certificate types incompatible with the handshake protocol version.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateRequest message even when client authentication is explicitly not required in the handshake context.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a malformed CertificateRequest message with invalid or corrupted fields, such as invalid length fields or unsupported algorithms.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Omit the CertificateRequest message entirely in a handshake scenario where client authentication is explicitly required.",
            "expected_behavior": "Timeout"
        }
    ]
}

