rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "Extension: key_share",
        "construction_rule": {
            "role": "server",
            "content": "When (EC)DHE is in use, the server MUST include the 'key_share' extension in its ServerHello message to indicate its selected key exchange parameters."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello, the client MUST verify the presence of the 'key_share' extension if (EC)DHE is in use. If the 'key_share' extension is missing, the client MUST abort the handshake with a 'missing_extension' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server fails to include the 'key_share' extension in its ServerHello message when (EC)DHE is in use, violating the requirement for key exchange parameter selection.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ServerHello message without the 'key_share' extension when (EC)DHE key exchange is in use.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ServerHello message with an empty 'key_share' extension (zero-length field) when (EC)DHE key exchange is in use.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ServerHello message with a malformed 'key_share' extension (e.g., an invalid or truncated key share value) when (EC)DHE key exchange is in use.",
            "expected_behavior": "Alert"
        }
    ]
}

