rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When sending 0-RTT data, the client MUST ensure that authentication is performed either via TLS client authentication or by mechanisms within the application protocol. This choice may affect replay protection guarantees."
        },
        "processing_rule": {
            "role": "server",
            "content": "If 0-RTT data is received, the server MUST recognize that weaker replay protection guarantees apply if authentication is performed via TLS client authentication or within the application protocol. The server MUST process such data while acknowledging the compromise in replay protection."
        }
    }
}

