rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions.key_share",
        "construction_rule": {
            "role": "server",
            "content": "If (EC)DHE key establishment is in use, the ServerHello message MUST include a 'key_share' extension containing the server's ephemeral Diffie-Hellman share. The server's share MUST belong to the same group as one of the client's shares included in the ClientHello."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the ServerHello, the client MUST validate that the server's ephemeral Diffie-Hellman share, within the 'key_share' extension, is in the same group as one of its own shares. If the server's share does not match any group of the client's shares, the client MUST abort the handshake with a 'handshake_failure' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server includes a 'key_share' extension in the ServerHello with an ephemeral Diffie-Hellman share that does not belong to any of the groups included in the client's shares from the ClientHello.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions.key_share",
            "description": "Send a ServerHello message with a 'key_share' extension containing a Diffie-Hellman share from a group not present in the ClientHello (e.g., if the ClientHello included groups X25519 and P-256, use P-384).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions.key_share",
            "description": "Send a ServerHello message with a 'key_share' extension containing an invalid group identifier not supported by the protocol.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions.key_share",
            "description": "Send a ServerHello with an empty 'key_share' extension (i.e., zero length server share) to simulate a missing key share.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions.key_share",
            "description": "Send a ServerHello message with a 'key_share' extension containing a correctly formatted but incompatible group that was explicitly excluded in the ClientHello groups.",
            "expected_behavior": "Alert"
        }
    ]
}

