rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST ensure the 'mandatory' vector in TLS 1.3 contains between 300 and 400 bytes of type opaque. The vector MUST never be empty and the actual length MUST be encoded in a 2-byte uint16."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST verify that the 'mandatory' vector's length is between 300 and 400 bytes when received. If the length is outside this range or the vector is empty, the server MUST terminate the connection with a 'decode_error' alert."
        }
    }
}

