rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "server",
            "content": "If the server selects a PSK and determines that the PSK can be used without (EC)DHE, the server can proceed with the handshake even if there is no overlap in the 'supported_groups' parameters between client and server."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the 'supported_groups' extension in ClientHello, the server must check for overlap in supported groups if PSK is not used exclusively without (EC)DHE. However, if a PSK is selected and it can work without (EC)DHE, lack of overlap in 'supported_groups' does not need to terminate the handshake."
        }
    }
}

strategy:
{
    "rule_violation": "The server proceeds with the handshake without using (EC)DHE when there is no overlap in supported groups, even when using a PSK that requires (EC)DHE.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message with supported_groups extension listing only groups not supported by the server, and initiate a PSK that requires (EC)DHE.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message without the supported_groups extension and initiate a PSK that requires (EC)DHE.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message with supported_groups extension containing only deprecated or inactive groups, and initiate a PSK that requires (EC)DHE.",
            "expected_behavior": "Alert"
        }
    ]
}

