        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "server",
            "content": "When constructing the ServerHello message, the server must include a supported set of cipher suites in tls.handshake.ciphersuites to complete a successful handshake."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the server is unable to negotiate a supported set of parameters from the received ClientHello message, it must abort the handshake with either a 'handshake_failure' or 'insufficient_security' fatal alert."
        }
    }
}

