rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.version",
        "construction_rule": {
            "role": "server",
            "content": "When sending ServerHello in TLS 1.3, the server MUST indicate its version using the 'supported_versions' extension and set the legacy_version field to 0x0303 (TLS 1.2) to maintain backward compatibility."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving ServerHello, the client MUST verify that the legacy_version field is set to 0x0303, indicating backward compatibility. If this field is not set as required, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

