rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "When provisioning PSKs out of band, the client MUST ensure that both the PSK identity and the KDF hash algorithm are provisioned along with the Pre-Shared Key."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST ensure that when it receives PSK identities provisioned out of band, the corresponding KDF hash algorithm is also provisioned and associated for proper PSK use."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to provision the PSK identity or the corresponding KDF hash algorithm when configuring PSKs out of band, violating the requirement for complete association between PSK identity and KDF hash algorithm.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with a PSK identity included in the Pre-Shared Key extension, but omit the indication of the KDF hash algorithm.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with an empty PSK identity in the Pre-Shared Key extension.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with a mismatched PSK identity and KDF hash algorithm pair that is not provisioned together.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with multiple PSK identities but only one corresponding KDF hash algorithm provisioned.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with a malformed PSK identity in the Pre-Shared Key extension (e.g., invalid length or corrupted identifier format).",
            "expected_behavior": "Alert"
        }
    ]
}

