        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "client",
            "content": "When sending 0-RTT data in TLS 1.3, the client must construct and send 0-RTT data without relying on any information from the server's Random value in the ServerHello since this data has weaker guarantees of replay protection."
        },
        "processing_rule": {
            "role": "server",
            "content": "When processing 0-RTT data in TLS 1.3, the server must not use the server's Random value or any information derived from it to verify or assume properties regarding replay protection, as 0-RTT data inherently provides weaker protections compared to 1-RTT data."
        }
    }
}

