        },
        "processing_rule": {
            "role": "client",
            "content": "A legacy TLS client performing renegotiation with TLS 1.2 or prior MUST check the tls.handshake.version field upon receiving ServerHello. If it is set to 0x0304 indicating TLS 1.3 during renegotiation, the client MUST abort the handshake with a 'protocol_version' alert."
        }
    }
}

