rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "The client must include only those cipher suites it can support in the tls.handshake.ciphersuites field during the ClientHello message."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must iterate through the tls.handshake.ciphersuites list. If the list contains cipher suites that the server does not recognize, support, or wish to use, the server MUST ignore those cipher suites and process the remaining ones as usual."
        }
    }
}

