rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST include the 'supported_groups' extension in ClientHello to indicate the (EC)DHE groups it supports. The list in 'tls.handshake.extensions_supported_groups' SHOULD be ordered by the client's preference."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST parse the 'supported_groups' extension in 'tls.handshake.extensions_supported_groups' to determine the (EC)DHE groups supported by the client. If this extension is missing, the server SHOULD assume default groups or terminate negotiation if no suitable group is found."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly include the 'supported_groups' extension in ClientHello or includes it incorrectly, violating the requirement to indicate supported (EC)DHE groups.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message without the 'supported_groups' extension, leaving the field completely absent.",
            "expected_behavior": "HelloRetryRequest"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message with an empty 'supported_groups' extension (i.e., zero-length list).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message with the 'supported_groups' extension containing invalid group identifiers, such as 0xFFFF.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message with the 'supported_groups' extension list in reverse-alphabetical order, not following client preference ordering.",
            "expected_behavior": "ServerHello"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extensions_supported_groups",
            "description": "Send a ClientHello message with a malformed 'supported_groups' extension, having an incorrect length field that doesn’t match the actual payload size.",
            "expected_behavior": "Alert"
        }
    ]
}

