rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "Extension: pre_shared_key",
        "construction_rule": {
            "role": "client",
            "content": "In its updated ClientHello, the client SHOULD NOT include any pre-shared keys in the Pre-Shared Key extension that are associated with a hash other than the hash of the selected cipher suite."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST check that any included pre-shared keys in the Pre-Shared Key extension are associated with a hash matching the selected cipher suite's hash. If they do not match, the server SHOULD ignore those pre-shared keys."
        }
    }
}

