rule:
{
  "structured_rule": {
    "protocol": "TLS 1.3",
    "message": "No Extension",
    "field": "tls.handshake",
    "construction_rule": {
      "role": "server",
      "content": "The server MUST send a HelloRetryRequest message in response to a ClientHello message if it finds an acceptable set of parameters but requires more information to proceed with the handshake."
    },
    "processing_rule": {
      "role": "client",
      "content": "Upon receiving the HelloRetryRequest message, the client MUST process the message and attempt to provide the necessary information in a subsequent ClientHello message to continue the handshake."
    }
  }
}

strategy:
{
    "rule_violation": "The server fails to send a HelloRetryRequest message when encountering a ClientHello message with acceptable parameters but requiring more information to proceed with the handshake.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message with parameters that require additional negotiation, such as utilizing an unsupported cipher suite, and verify that the server does not respond with a HelloRetryRequest message.",
            "expected_behavior": "HelloRetryRequest"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message that includes incomplete or conflicting key share data and check if the server responds with a HelloRetryRequest message to resolve the issue.",
            "expected_behavior": "HelloRetryRequest"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message with the supported_groups extension listing only groups the server does not prefer and verify whether a HelloRetryRequest message is sent to resolve the group mismatch.",
            "expected_behavior": "HelloRetryRequest"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message listing an incorrectly formatted record_size_limit extension and check whether the server fails to respond with the necessary HelloRetryRequest message.",
            "expected_behavior": "HelloRetryRequest"
        }
    ]
}

