            "content": "When a client first connects to a server, it is REQUIRED that the client send the ClientHello message as the first handshake message in the TLS connection."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the first message from a client, the server MUST verify that the message type is ClientHello. If the first message is not ClientHello, the server MUST abort the handshake with an 'unexpected_message' alert."
        }
    }
}

