rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "server",
            "content": "The server MUST generate 32 bytes for tls.handshake.random using a secure random number generator. If negotiating TLS 1.2 or TLS 1.1, the last 8 bytes MUST be overwritten, but the remaining bytes MUST remain random. This generation MUST be independent of ClientHello.random."
        },
        "processing_rule": {
            "role": "client",
            "content": "The client MUST process the tls.handshake.random field, ensuring that except for the last 8 bytes (in case of TLS 1.2 or TLS 1.1), the bytes remain random as received in ServerHello for TLS 1.3."
        }
    }
}

strategy:
{
    "rule_violation": "The server generates the tls.handshake.random field incorrectly, either by not using a secure random number generator, by failing to ensure the randomness of the initial 24 bytes (TLS 1.2/1.1), or by overwriting unrelated parts.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the tls.handshake.random field entirely filled with a fixed, non-random pattern (e.g., all bytes set to 0x00).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the tls.handshake.random field duplicated from the ClientHello.random field, violating the independence requirement.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the tls.handshake.random field having bytes with incorrect overwrite position (modifying random bytes other than the last 8 for TLS 1.2/1.1).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the tls.handshake.random field where randomness is partially compromised (e.g., the first 24 bytes are set to a predictable sequence like 0x01, 0x02, ..., 0x18).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with invalid tls.handshake.random field length (e.g., less than the required 32 bytes).",
            "expected_behavior": "Alert"
        }
    ]
}

