rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message, the client MUST include the Supported Versions Extension containing all versions of TLS it is prepared to negotiate. This MUST include at least 0x0304 (TLS 1.3), and if earlier versions of TLS are supported for negotiation, they MUST also be included."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST verify that the Supported Versions Extension contains at least 0x0304 (TLS 1.3). If earlier versions are included and are supported by the server, they may also be considered for negotiation. If the extension is malformed or missing required versions, the server MUST abort the handshake with an appropriate alert."
        }
    }
}

strategy:
{
