        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.session_id_length",
        "construction_rule": {
            "role": "client",
            "content": "When sending ClientHello without session resumption, client MUST set the legacy_session_id field as a zero-length vector, meaning the tls.handshake.session_id_length field MUST be set to 0."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST verify that the legacy_session_id field in the received ClientHello is set as a zero-length vector when session resumption is not used. If not, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

