    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "server",
            "content": "When sending ServerHello, the server MUST include the same cipher suite in the tls.handshake.ciphersuites field as it did in any preceding HelloRetryRequest sent to the client."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the ServerHello, the client MUST verify that the cipher suite in tls.handshake.ciphersuites matches the one sent in any HelloRetryRequest received earlier. If they differ, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
