        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity",
        "construction_rule": {
            "role": "server",
            "content": "After the initial handshake in TLS 1.3, the server can send a PSK identity in the tls.handshake.extensions.psk.identity field to the client, which corresponds to a unique key derived from the initial handshake. This identity must be used by the client in subsequent handshakes to reference the associated Pre-Shared Key (PSK) for faster session resumption."
        },
        "processing_rule": {
            "role": "client",
            "content": "The client, upon receiving a PSK identity in the Pre Shared Key Extension, must store this identity along with the associated PSK. In future handshakes, when resuming a session, the client must include this identity in the tls.handshake.extensions.psk.identity field to negotiate use of the associated PSK. If accepted by the server, the security context of the new connection must be cryptographically tied to the original connection, and the key derived from the initial handshake will be used to bootstrap the cryptographic state."
        }
    }
}

