rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "client",
            "content": "To construct a TLS 1.3 ClientHello, the client MUST set the legacy_version field to 0x0303 and include the supported_versions extension with 0x0304 as the highest version indicated."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST identify the message as a TLS 1.3 ClientHello if the legacy_version is set to 0x0303 and the supported_versions extension is present with 0x0304 as the highest version indicated. If these conditions are not met, the server MUST treat the message as non-compliant."
        }
    }
}

