strategy:
{
    "rule_violation": "The client does not wait for a ServerHello or HelloRetryRequest message after sending the ClientHello, violating the expected handshake flow.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message, followed by immediately sending random application data, without waiting for the ServerHello or HelloRetryRequest.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message, followed by immediately closing the connection without waiting for a ServerHello or HelloRetryRequest.",
            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message, followed by another identical ClientHello message without waiting for the ServerHello or HelloRetryRequest.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a ClientHello message and then wait an abnormally short time (e.g., 1 millisecond) before sending random data, effectively not waiting for the ServerHello or HelloRetryRequest.",
            "expected_behavior": "Alert"
        }
    ]
}

