rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "When sending a ClientHello in TLS 1.3, the client MUST include the 'supported_versions' extension, ensuring that 'tls.handshake.extensions_length' is non-zero to avoid misinterpretation as a TLS 1.2 ClientHello."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server MUST check that 'tls.handshake.extensions_length' is non-zero, indicating the presence of extensions. If extensions are absent, the message should be interpreted as a TLS 1.2 ClientHello."
        }
    }
}

