    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Signature Algorithms Extension in ClientHello, if the public key is carried in an X.509 certificate, client MUST ensure that it uses the rsaEncryption OID."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension, the server must verify that if the public key is in an X.509 certificate, it uses the rsaEncryption OID. If not, the server must reject the certificate and terminate the connection with an appropriate alert."
        }
    }
}

