rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message, the client MUST generate a 32-byte value for the tls.handshake.random field. This value need not be random but SHOULD be unpredictable to prevent ossification."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello message, the server SHOULD NOT assume the tls.handshake.random value adheres to a fixed pattern and should handle it as an unpredictable 32-byte value."
        }
    }
}

strategy:
{
  "rule_violation": "The client fails to generate an unpredictable 32-byte value for the tls.handshake.random field in the ClientHello message, potentially enabling ossification.",
  "testing_strategies": [
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.handshake.random",
      "description": "Send a ClientHello message with the tls.handshake.random field set to a fixed and predictable pattern, such as all zeros (0x00).",
      "expected_behavior": "Alert"
    },
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.handshake.random",
      "description": "Send a ClientHello message with the tls.handshake.random field set to an incrementing counter (e.g., 0x00000001, 0x00000002, ..., 0x00000020).",
      "expected_behavior": "Alert"
    },
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.handshake.random",
      "description": "Send a ClientHello message with the tls.handshake.random field set to a repeated pattern, such as alternating bytes (e.g., 0xABABABAB...).",
      "expected_behavior": "Alert"
    },
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.handshake.random",
      "description": "Send a ClientHello message with the tls.handshake.random field set to a known, non-random fixed value commonly used in previous tests.",
      "expected_behavior": "Alert"
    }
  ]
}

