        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello in response to a HelloRetryRequest, the client must use the 'supported_versions' extension to communicate supported protocol versions."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receipt of a HelloRetryRequest, the client must check and confirm the legacy_version, legacy_session_id_echo, cipher_suite, and legacy_compression_method as specified in Section 4.1.3. After verifying these fields, the client must process the extensions and use the 'supported_versions' extension to determine the protocol version."
        }
    }
}

