rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "server",
            "content": "When constructing a HelloRetryRequest, the server MUST NOT include any extensions that were not first offered by the client in its ClientHello, except for the 'cookie' extension, which may optionally be added by the server."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a HelloRetryRequest, the client MUST verify that the extensions in the message are a subset of those offered in its ClientHello, except for the optional 'cookie' extension. If the condition is violated, the handshake MUST be aborted with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server includes extensions in the HelloRetryRequest that were not first offered by the client in its ClientHello, violating the limitation of extension inclusion, except for the optional 'cookie' extension.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a HelloRetryRequest containing an unsupported extension not present in the original ClientHello, such as 'supported_groups'.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a HelloRetryRequest including the 'key_share' extension, which was not offered in the original ClientHello.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a HelloRetryRequest with a non-existent or unknown extension tag, ensuring the extension was not originally offered in ClientHello.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a HelloRetryRequest with multiple new extensions that were not offered in ClientHello, such as 'max_fragment_length' and 'client_certificate_type'.",
            "expected_behavior": "Alert"
        }
    ]
}

