rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_client_length",
        "construction_rule": {
            "role": "server",
            "content": "When constructing ServerHello messages in TLS 1.3 using a PSK with (EC)DHE key establishment, the server MUST include either the 'pre_shared_key' extension, the 'key_share' extension, or both."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello message, the client MUST verify that the message contains either the 'pre_shared_key' extension, the 'key_share' extension, or both when a PSK with (EC)DHE key establishment is used. If neither extension is present, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

