        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "The client must include only 'PureEdDSA' algorithms in the 'tls.handshake.sig_hash_algs' field when specifying signature algorithms using EdDSA as defined in RFC8032 or its successors."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension, the server must ensure that only 'PureEdDSA' algorithms are listed in the 'tls.handshake.sig_hash_algs' field. If a 'prehash' variant is found, the server must reject the extension and terminate the handshake with an appropriate alert."
        }
    }
}

