rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "server",
            "content": "In ServerHello messages indicating TLS 1.2 or below, the server MUST set the last 8 bytes of the 'tls.handshake.random' field to values other than those prohibited by TLS 1.3 to maintain backward compatibility."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello indicating TLS 1.2 or below, the client MUST check that the last 8 bytes of the 'tls.handshake.random' field do not match any of the prohibited values. If a match is found, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server includes prohibited values in the last 8 bytes of the 'tls.handshake.random' field in a ServerHello message indicating TLS 1.2 or below, violating the compatibility requirements for legacy versions.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message indicating TLS 1.2 with the last 8 bytes of the 'tls.handshake.random' field set to 0x0000000000000000 (a prohibited value).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message indicating TLS 1.2 with the last 8 bytes of the 'tls.handshake.random' field set to 0x0101010101010101 (a prohibited value).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message indicating TLS 1.2 with the last 8 bytes of the 'tls.handshake.random' field set to a repeating pattern of 0x1E (0x1E1E1E1E1E1E1E1E, a prohibited value).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message indicating TLS 1.2 with the last 8 bytes of the 'tls.handshake.random' field set to all 0xFFs (0xFFFFFFFFFFFFFFFF, a prohibited value).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message indicating TLS 1.2 with the last 8 bytes of the 'tls.handshake.random' field deliberately corrupted to include an invalid encoding that intentionally violates the prohibited values list.",
            "expected_behavior": "Alert"
        }
    ]
}

