rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "server",
            "content": "When negotiating TLS 1.1 or below, the server MUST set the last 8 bytes of the ServerHello.Random value to 44 4F 57 4E 47 52 44 00."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello, if negotiating TLS 1.1 or below, the client MUST verify that the last 8 bytes of the ServerHello.Random are set to 44 4F 57 4E 47 52 44 00. If not, the connection must be terminated with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server fails to set the last 8 bytes of the ServerHello.Random value to 44 4F 57 4E 47 52 44 00 when negotiating TLS 1.1 or below.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the last 8 bytes of the ServerHello.Random set to all zeros (00 00 00 00 00 00 00 00) instead of 44 4F 57 4E 47 52 44 00.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the last 8 bytes of the ServerHello.Random set to the incorrect value (e.g., 11 22 33 44 55 66 77 88).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the last 8 bytes of the ServerHello.Random omitted entirely.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ServerHello message with the last 8 bytes of the ServerHello.Random set to partly correct values (e.g., 44 4F 57 4E 00 00 00 00).",
            "expected_behavior": "Alert"
        }
    ]
}

