rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the ClientHello message in TLS 1.3, the client may include the 'signature_algorithms_cert' extension to indicate supported signature algorithms for certificates."
        },
        "processing_rule": {
            "role": "server",
            "content": "TLS 1.2 implementations SHOULD process the 'signature_algorithms_cert' extension within the ClientHello message to determine the client's supported signature algorithms for certificates. If the server supports this extension, it may consider it in conjunction with 'tls.handshake.sig_hash_algs' to choose an appropriate certificate."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes invalid or unsupported signature algorithms within the 'signature_algorithms_cert' extension in the ClientHello message, improperly indicating supported signature algorithms for certificates.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message where 'signature_algorithms_cert' extension includes an unrecognized or unassigned signature algorithm code.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message where 'signature_algorithms_cert' extension includes an empty list of signature algorithms.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message where 'signature_algorithms_cert' extension includes duplicate entries for the same signature algorithm.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message where 'signature_algorithms_cert' extension uses algorithms deprecated in TLS 1.3.",
            "expected_behavior": "Alert"
        }
    ]
}

