rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "Extension: pre_shared_key",
        "construction_rule": {
            "role": "server",
            "content": "In ServerHello, when using a PSK with (EC)DHE key establishment, server MUST include either the 'pre_shared_key' extension, the 'key_share' extension, or both."
        },
        "processing_rule": {
            "role": "client",
            "content": "The client MUST verify that the ServerHello includes the 'pre_shared_key' extension, the 'key_share' extension, or both when a PSK with (EC)DHE key establishment is used. If neither extension is present, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

