        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the CertificateRequest message, the client should check for the presence of the 'certificate_authorities' extension in the tls.handshake.extensions_length field, although its presence is optional."
        }
    }
}

strategy:
