            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a CertificateRequest message with malformed extensions data, causing the extensions_length field to misrepresent the actual size of the extensions.",
            "expected_behavior": "Alert"
        }
    ]
}

