        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "server",
            "content": "When constructing the Certificate message, the server MUST NOT offer a SHA-1 signed certificate unless no valid certificate chain can be produced without it."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a certificate chain, the client MUST verify the signature algorithms used in the chain against the Signature Algorithms Extension. If SHA-1 is used and a valid certificate chain without SHA-1 was possible, the client MUST consider the certificate chain invalid and terminate the connection."
        }
    }
}

