        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "client",
            "content": "If a client chooses to support prior versions of TLS, it SHOULD include TLS 1.2 in the supported_version list within the ClientHello message."
        },
        "processing_rule": {
            "role": "server",
            "content": "When receiving a ClientHello with the supported_versions extension, if the server supports prior versions of TLS, it SHOULD ensure TLS 1.2 is among the versions if it advertises support for these prior versions. Otherwise, the server may proceed with TLS 1.3."
        }
    }
}

