            "content": "Legacy algorithms MAY be included in the 'signature_algorithms' and 'signature_algorithms_cert' fields for backward compatibility with TLS 1.2, but these algorithms are not to be used for generating signed TLS handshake messages."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension, the server may recognize legacy algorithms listed in 'signature_algorithms' and 'signature_algorithms_cert' fields for TLS 1.2 compatibility. However, the server must ensure these algorithms are not employed for signed TLS 1.3 handshake messages."
        }
    }
}

