      "content": "In TLS 1.3, clients that advertise support for RSASSA-PSS in the Signature Algorithms Extension MUST include the corresponding entries for RSASSA-PSS algorithms in the 'tls.handshake.sig_hash_algs' field when constructing the ClientHello message."
    },
    "processing_rule": {
      "role": "server",
      "content": "When receiving a ClientHello message, servers in TLS 1.3 MUST verify that they support the advertised RSASSA-PSS algorithms included in the 'tls.handshake.sig_hash_algs' field. Additionally, even when TLS 1.2 is negotiated, the server MUST be prepared to accept and validate signatures using the RSASSA-PSS scheme if it has been advertised by the client."
    }
  }
}

