rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "client",
            "content": "When advertising supported groups in the ClientHello, the client MUST include all elliptic curves that it is willing to accept for signatures, as part of the 'supported_groups' extension."
        },
        "processing_rule": {
            "role": "server",
            "content": "If TLS 1.2 is negotiated, the server MUST validate that any signature received uses a curve that was advertised in the client's 'supported_groups' extension. If a signature utilizes a curve not included in the 'supported_groups' extension, the handshake MUST fail, and the server MUST terminate the connection with an appropriate alert."
        }
    }
}

