rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "server",
            "content": "When sending a HelloRetryRequest, the server MUST ensure that the modifications to the ClientHello will result in a different configuration to continue the handshake process."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a HelloRetryRequest, the client MUST compare the proposed parameters to those sent in the original ClientHello. If the changes do not result in any modification to the subsequent ClientHello, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server sends a HelloRetryRequest with modifications that do not result in a different configuration, violating the requirement for meaningful changes to continue the handshake.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a HelloRetryRequest with the proposed parameters identical to those in the original ClientHello, resulting in no changes to the subsequent ClientHello.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a HelloRetryRequest with cipher suites that match those offered in the original ClientHello, without proposing any new options.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a HelloRetryRequest requesting a new elliptic curve group identical to the ones supported in the original ClientHello.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a HelloRetryRequest with session tickets offered in the original ClientHello, without suggesting any alterations.",
            "expected_behavior": "Alert"
        }
    ]
}

