    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST populate the 'tls.handshake.sig_hash_algs' field in the Signature Algorithms Extension with a list of SignatureScheme values in descending order of preference. Each SignatureScheme value MUST indicate a signature algorithm that the client is willing to verify, and it MUST specify that the algorithm takes as input an arbitrary-length message rather than a digest."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension, the server MUST process the 'tls.handshake.sig_hash_algs' field to determine the client's preferred signature algorithms. The server MUST ensure that each value is a valid SignatureScheme and that the algorithms listed align with the requirement of taking as input an arbitrary-length message rather than a digest. If any invalid or unsupported values are encountered, the server MUST abort the handshake and send an 'illegal_parameter' alert."
        }
    }
}

