rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions.certificate_authorities",
        "construction_rule": {
            "role": "client",
            "content": "When including the 'certificate_authorities' extension in ClientHello, the client MUST list the certificate authorities (CAs) that it supports and indicates to the server which CAs should be used to guide certificate selection."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the 'certificate_authorities' extension in ClientHello, the server SHOULD use the provided list of certificate authorities to guide its certificate selection process. If no suitable certificate can be selected, the server MUST terminate the handshake with an appropriate alert."
        }
    }
}

