rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When including the SignatureSchemeList in the Signature Algorithms Extension, the client MUST list legacy algorithms (SHA-1 with either RSA using RSASSA-PKCS1-v1_5 or ECDSA) as the lowest priority, after all other algorithms."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension, the server MUST verify that the client has placed legacy algorithms (SHA-1 with either RSA using RSASSA-PKCS1-v1_5 or ECDSA) as the lowest priority in the SignatureSchemeList. If this condition is not met, the server MAY respond with an alert or downgrade the priority of such algorithms during its own signature scheme selection."
        }
    }
}

