    "rule_violation": "The client incorrectly prioritizes legacy algorithms (SHA-1 with either RSA using RSASSA-PKCS1-v1_5 or ECDSA) above other algorithms in the SignatureSchemeList within the Signature Algorithms Extension.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with legacy algorithm SHA-1 with RSA RSASSA-PKCS1-v1_5 listed at the highest priority in the SignatureSchemeList.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with legacy algorithm SHA-1 with ECDSA listed at the highest priority in the SignatureSchemeList.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with legacy algorithms interleaved with other algorithms, not strictly at the lowest priority.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Signature Algorithms Extension in ClientHello, the client SHOULD NOT include deprecated algorithms like SHA-1 with RSASSA-PKCS1-v1_5 or ECDSA unless necessary for backward compatibility purposes."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension in ClientHello, the server SHOULD NOT select deprecated algorithms like SHA-1 with RSASSA-PKCS1-v1_5 or ECDSA unless required for backward compatibility with the client."
        }
    }
}

