rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "The client MAY include RSASSA-PKCS1-v1_5 algorithms in tls.handshake.sig_hash_algs for backward compatibility with TLS 1.2, solely for signatures in certificates, and MUST NOT use them for signed TLS handshake messages."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms Extension, the server MUST ensure RSASSA-PKCS1-v1_5 algorithms are only used for signatures in certificates and are ignored for signed TLS handshake messages, complying with TLS 1.3 requirements."
        }
    }
}

strategy:
{
    "rule_violation": "The client violates the construction rule by including RSASSA-PKCS1-v1_5 algorithms in tls.handshake.sig_hash_algs and attempting to use these algorithms for signed TLS handshake messages, which is explicitly disallowed in TLS 1.3.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension including RSASSA-PKCS1-v1_5 algorithms and use those algorithms for signing the TLS handshake messages.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension including only RSASSA-PKCS1-v1_5 algorithms and no supported TLS 1.3-compliant algorithms.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with malformed Signature Algorithms Extension that includes duplicate RSASSA-PKCS1-v1_5 entries to simulate improper configuration.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension including RSASSA-PKCS1-v1_5 algorithms and attempt to sign Server Key Exchange messages using these algorithms, violating TLS 1.3 requirements.",
            "expected_behavior": "Alert"
        }
    ]
}

