rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "The client must signal its willingness to support post-handshake authentication by including the post_handshake_auth extension in the ClientHello message."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST NOT send a post-handshake CertificateRequest to a client that did not include the post_handshake_auth extension in the ClientHello message."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to include the post_handshake_auth extension in the ClientHello message, violating the requirement to signal support for post-handshake authentication.",
    "testing_strategies": [
