rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message, the client MAY accept a certificate that begins a certification path even if it uses a signature algorithm not listed in the 'tls.handshake.sig_hash_algs' field of the 'signature_algorithms' extension."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a certification path from the client, the server MAY process a certificate that begins a certification path even if it uses a signature algorithm that is not listed as supported in the 'tls.handshake.sig_hash_algs' field of the 'signature_algorithms' extension."
        }
    }
}

