rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "client",
            "content": "When sending the Supported Groups Extension in ClientHello, the client must ensure that values in the tls.handshake.extensions_supported_groups field range from 0x0000 to 0xFDFF, as values 0xFE00 through 0xFEFF are reserved for Private Use."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving Supported Groups Extension in ClientHello, the server must verify that values in the tls.handshake.extensions_supported_groups field do not include any values between 0xFE00 and 0xFEFF. If such values are encountered, the server must ignore them or reject the handshake."
        }
    }
}

