rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When sending the signature_algorithms extension in ClientHello, the client MUST list the signature and hash algorithm pairs it supports, ensuring ECDSA algorithms correspond to a valid EC curve and hash algorithm, with signatures represented as DER-encoded ECDSA-Sig-Value structures."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the signature_algorithms extension, the server MUST validate each listed ECDSA algorithm against its capabilities, ensuring compatibility with the specified EC curve and hash algorithm. The server MUST expect a DER-encoded ECDSA-Sig-Value structure for the signature and reject the handshake if improper formatting is detected."
        }
    }
}

