    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client",
            "content": "In the psk_dhe_ke mode, the client must include a Key Share Extension in the ClientHello message with 'key_share' values detailing supported key exchange methods, as described in Section 4.2.8."
        },
        "processing_rule": {
            "role": "server",
            "content": "In the psk_dhe_ke mode, the server must verify the presence and validity of the Key Share Extension in the ClientHello message with 'key_share' values. The server MUST respond with its own 'key_share' values in the ServerHello message."
        }
    }
}

