rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "If a PSK is used and early data is allowed for that PSK, the client MUST include the 'early_data' extension in its first flight of messages when it chooses to send Application Data."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the 'early_data' extension is present in the client's first flight of messages, the server MUST validate that the associated PSK allows early data. If early data is not allowed for the PSK, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
