rule:
{
  "structured_rule": {
    "protocol": "TLS 1.3",
    "message": "Psk Key Exchange Modes Extension",
    "field": "tls.extension.psk_ke_mode",
    "construction_rule": {
      "role": "client",
      "content": "When using PSKs, the client MUST include the 'psk_key_exchange_modes' extension in the ClientHello message. The client MUST use this extension to indicate the supported PSK key exchange modes, restricting the use of PSKs offered in this ClientHello and those the server might supply via NewSessionTicket."
    },
    "processing_rule": {
      "role": "server",
      "content": "If the 'psk_key_exchange_modes' extension is not present in the ClientHello message, the server MUST NOT attempt to use PSKs for the key exchange. The server MUST verify that the PSK key exchange mode used corresponds to the modes indicated by the client in the 'psk_key_exchange_modes' extension; otherwise, the server MUST abort the handshake with an 'illegal_parameter' alert."
    }
  }
}

