rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "client",
            "content": "When sending the Supported Groups Extension in ClientHello, client MUST list elliptic curve groups (ECDHE) that it supports, selecting from curves named in FIPS 186-4 or RFC7748."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Supported Groups Extension in ClientHello, server MUST verify that the curves listed are named curves from FIPS 186-4 or RFC7748. If none of the client's supported groups match the server's preferences, it may select a named group from these standards or indicate no shared group."
        }
    }
}

strategy:
