    "rule_violation": "The server fails to include its own 'early_data' extension in the EncryptedExtensions, violating the requirement to indicate intent to process early data.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send an EncryptedExtensions message without the 'early_data' extension when processing early data.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send an EncryptedExtensions message with an empty 'early_data' extension field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send an EncryptedExtensions message with the 'early_data' extension presented but with an incorrect value.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "server",
            "content": "When processing early data, the server must include its own 'early_data' extension in the EncryptedExtensions to indicate that it intends to process the early data."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving EncryptedExtensions, the client must check for the presence of the server's 'early_data' extension to confirm that the server intends to process early data. If the extension is missing, the client must abort the early data processing."
        }
    }
}

