rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "server",
            "content": "When sending ServerHello, server MUST include the supported_versions extension to indicate the protocol version selected."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving ServerHello, if the supported_versions extension is present, the client MUST check this extension before processing the rest of the ServerHello. If the extension is not found, the client should abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
