rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extension.type",
        "construction_rule": {
            "role": "client",
            "content": "If a PSK is used and early data is allowed, the client must include the 'pre_shared_key' extension when sending the initial flight of Application Data."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server must check for the presence of the 'pre_shared_key' extension if early data and PSK usage are indicated. If this extension is missing, and early data was expected, the server must reject the early data."
        }
    }
}

strategy:
{
    "rule_violation": "The client does not include the 'pre_shared_key' extension in the ClientHello when using a PSK and allowing early data, violating the requirement to include this extension.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message when a PSK is used and early data is enabled, but omit the 'pre_shared_key' extension entirely.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message with the 'pre_shared_key' extension included but improperly formatted, such as providing an empty PSK list.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message indicating early data usage but include a 'pre_shared_key' extension referencing an invalid or nonexistent PSK identity.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message where the PSK identifier in the 'pre_shared_key' extension does not match the server’s expectations for early data compatibility.",
            "expected_behavior": "Alert"
        }
    ]
}

