rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "server",
            "content": "When sending the supported_groups extension in TLS 1.3, server MUST include a list of elliptic curve groups that comply with the client's requirements if needed."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the supported_groups extension in a ServerHello, the client MUST process and use the elliptic curve groups as suggested, or otherwise handle according to its capabilities."
        }
    }
}

