rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "For 0-RTT messages sent in the first flight, the client must ensure that the tls.record.content_type matches the content types used for handshake and application_data messages, but these messages must be encrypted using keys specific to 0-RTT protection."
        },
        "processing_rule": {
            "role": "server",
            "content": "When receiving 0-RTT messages, the server must verify that the tls.record.content_type corresponds to the known content types (e.g., for handshake or application_data). These messages must be decrypted using the appropriate 0-RTT keys. If the content type is invalid or decryption fails, the server must reject the message and terminate the connection."
        }
    }
}

strategy:
{
    "rule_violation": "The client uses an incorrect or unexpected tls.record.content_type for 0-RTT messages, or fails to encrypt these messages using the proper 0-RTT protection keys.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 0-RTT message with an invalid content_type (e.g., content_type set to 0xFF which is not defined for TLS).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 0-RTT message with the content_type set to handshake (0x16) but without using 0-RTT encryption keys.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 0-RTT message with the content_type set to application_data (0x17) but encrypted with incorrect keys that are not related to 0-RTT.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 0-RTT message with the content_type set to change_cipher_spec (0x14) which is not proper for 0-RTT messages.",
            "expected_behavior": "Alert"
        }
    ]
}

