rule:
{
  "structured_rule": {
    "protocol": "TLS 1.3",
    "message": "Pre Shared Key Extension",
    "field": "Extension: pre_shared_key",
    "construction_rule": {
      "role": "client",
      "content": "If the client includes the 'pre_shared_key' extension in the ClientHello, it MUST also include the 'psk_key_exchange_modes' extension to indicate the key exchange modes that it supports."
    },
    "processing_rule": {
      "role": "server",
      "content": "Upon receiving a ClientHello with a 'pre_shared_key' extension and without a 'psk_key_exchange_modes' extension, the server MUST abort the handshake."
    }
  }
}

