        "protocol": "TLS 1.3",
        "message": "Psk Key Exchange Modes Extension",
        "field": "Extension: psk_key_exchange_modes",
        "construction_rule": {
            "role": "client",
            "content": "If a client offers a 'pre_shared_key' extension, it MUST also include a 'psk_key_exchange_modes' extension to specify the key exchange modes."
        },
        "processing_rule": {
