rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_group",
        "construction_rule": {
            "role": "server",
            "content": "When using (EC)DHE key establishment in TLS 1.3, the server MUST include exactly one KeyShareEntry in the ServerHello. The 'tls.handshake.extensions_key_share_group' field in the KeyShareEntry MUST be identical to the group in the KeyShareEntry provided by the client selected for the negotiated key exchange."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a KeyShareEntry in the ServerHello, the client MUST verify that the 'tls.handshake.extensions_key_share_group' matches the group in the KeyShareEntry it sent in the ClientHello that was selected by the server. If the groups do not match, the client MUST terminate the handshake with a fatal 'illegal_parameter' alert."
        }
    }
}

