rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "When sending early data with the 'early_data' extension, the client must ensure that the record layer correctly marks these records with the appropriate content type for early data."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the server accepts the 'early_data' extension and subsequently fails to decrypt a 0-RTT record, it must terminate the connection with a 'bad_record_mac' alert, adhering to error-handling standards for all records."
        }
    }
}

strategy:
