            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLS 1.3 ClientHello message with the 'early_data' extension and transmit early data marked with a content type value reserved for handshake messages (e.g., 0x16).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLS 1.3 ClientHello message with the 'early_data' extension and transmit early data marked with a content type value reserved for application data (e.g., 0x17) instead of the appropriate early data type.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLS 1.3 ClientHello message with the 'early_data' extension and transmit early data with inconsistent content type values across different records within the same session.",
            "expected_behavior": "Alert"
        }
    ]
}

