rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client, server",
            "content": "When constructing a KeyShareEntry in a KeyShare structure for the Key Share Extension, both clients and servers MUST encode the Diffie-Hellman parameters in the opaque tls.handshake.extensions_key_share_key_exchange field. The opaque value MUST contain the Diffie-Hellman public value (Y = g^X mod p) for the specified group. The value MUST be encoded as a big-endian integer and padded to the left with zeros to the size of p in bytes."
        },
        "processing_rule": {
            "role": "client, server",
            "content": "Upon receiving a KeyShareEntry in a KeyShare structure for the Key Share Extension, both clients and servers MUST validate that the tls.handshake.extensions_key_share_key_exchange field contains the Diffie-Hellman public value (Y = g^X mod p) for the specified group. The value MUST be encoded as a big-endian integer and padded to the left with zeros to the size of p in bytes. If the field is improperly encoded or does not meet these requirements, the Key Share Extension MUST be rejected, and the handshake terminated with an appropriate error."
        }
    }
}

strategy:
{
    "rule_violation": "The KeyShareEntry in the Key Share Extension fails to properly encode the Diffie-Hellman public value (Y = g^X mod p) as a big-endian integer padded to the left with zeros to the size of p in bytes, violating the encoding requirements.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
