            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a KeyShareEntry with the Diffie-Hellman public value padded with additional leading bytes beyond the size of p in bytes.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a KeyShareEntry with a malformed Diffie-Hellman public value that is entirely invalid (e.g., a random byte sequence that does not correspond to g^X mod p).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a KeyShareEntry with the Diffie-Hellman public value replaced with a zero-length value.",
            "expected_behavior": "Alert"
        }
    ]
}

