rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "If the 'early_data' extension is included in the ClientHello and later rejected by the server, the client application SHOULD NOT automatically retransmit the Application Data initially sent in early data after the handshake completes. Instead, retransmission requires explicit application-level logic to prevent incorrect assumptions about connection status."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the server receives a ClientHello containing the 'early_data' extension and decides to reject it, the server MUST perform the handshake without processing the early data. The server SHOULD indicate the rejection of early data in its response to ensure compliance."
        }
    }
}

