rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "When sending a Pre-Shared Key extension in ClientHello, the 0-RTT data parameters such as version and cipher suite must match those associated with the chosen PSK. For externally provisioned PSKs, these parameters must be consistent with the provisioning details."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Pre-Shared Key extension in ClientHello, the server must verify that the 0-RTT data parameters such as version, cipher suite, and ALPN protocol correspond to those associated with the PSK. If the PSK is externally provisioned, the server must ensure that parameters match the provisioned values."
        }
    }
}

