rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_group",
        "construction_rule": {
            "role": "client",
            "content": "When sending a ClientHello including the Key Share extension, the client MUST NOT offer any KeyShareEntry values for groups not listed in the 'supported_groups' extension."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message containing the Key Share extension, the server MUST check that the KeyShareEntry values correspond to groups listed in the client's 'supported_groups' extension. If any offered group is not supported, the server MUST ignore that group."
        }
    }
}

strategy:
