rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "When attempting a 0-RTT handshake, the client must ensure that its first flight of messages is constructed with proper 0-RTT record protection keys and follows the standard TLS Record structure, primarily for the 'tls.record.content_type' field."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the server rejects the 0-RTT handshake and does not have the 0-RTT record protection keys, the server must use trial decryption to process the incoming 'tls.record.content_type' field and locate the first non-0-RTT message. The server will either use 1-RTT handshake keys or search for a cleartext ClientHello in the presence of a HelloRetryRequest."
        }
    }
}

