rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "For externally established Pre-Shared Keys (PSKs), the client must ensure that all associated values, such as the identity in 'tls.handshake.extensions.psk.identity.identity', are provisioned along with the key. These values must be included in the Pre-Shared Key extension when constructing the ClientHello message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Pre-Shared Key extension in the ClientHello, the server must verify that the associated values for externally established Pre-Shared Keys (PSKs), such as 'tls.handshake.extensions.psk.identity.identity', match those provisioned along with the key. If a mismatch occurs, the server must reject the PSK and proceed without using it."
        }
    }
}

