rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identities",
        "construction_rule": {
            "role": "client",
            "content": "When sending the Pre Shared Key Extension in ClientHello, the client MUST provide a list of PSK identities that the server can choose from. Each identity MUST be associated with the cipher suite(s) that it supports, if applicable."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST ensure that it selects a PSK and a compatible cipher suite from the provided PSK identities. If no compatible cipher suite is found, or if the PSK does not specify an algorithm, the server MUST default to using SHA-256."
        }
    }
}

