rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
        "construction_rule": {
            "role": "client",
            "content": "For identities established externally, the client SHOULD use an obfuscated_ticket_age of 0."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST ignore the obfuscated_ticket_age value when the identity is established externally."
        }
    }
}

strategy:
