rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Psk Key Exchange Modes Extension",
        "field": "tls.extension.psk_ke_mode",
        "construction_rule": {
            "role": "client",
            "content": "When sending the ClientHello, the client must list all supported PSK key exchange modes in the psk_key_exchange_modes extension."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server must not select a PSK key exchange mode that is not listed by the client in the psk_key_exchange_modes extension. If no compatible mode is found, the server should abort the handshake."
        }
    }
}

strategy:
