rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity",
        "construction_rule": {
            "role": "server",
            "content": "The server's chosen identity must be expressed as a 0-based index pointing to one of the identities in the client's 'tls.handshake.extensions.psk.identity' list in the Pre-Shared Key Extension."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the server's 0-based index indicating the chosen identity, the client must verify that the index corresponds to a valid entry in its 'tls.handshake.extensions.psk.identity' list. If the index is invalid or out of bounds, the client must abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

