    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
        "construction_rule": {
            "role": "server",
            "content": "When constructing the NewSessionTicket message, the server MUST calculate the obfuscated_ticket_age field using the guidelines in Section 4.2.11.1. The calculation involves taking the difference between the client's presented ticket age and the age of the ticket as measured by the server, then adding the server processing time."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the NewSessionTicket message, the client MUST verify that the obfuscated_ticket_age field complies with the guidelines specified in Section 4.2.11.1. If the field is not constructed correctly, the client MUST reject the ticket and MUST NOT use it to establish a connection."
        }
    }
}

