rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.session_id",
        "construction_rule": {
            "role": "server",
            "content": "When requesting post-handshake authentication, the server SHOULD make the tls.handshake.session_id (used as certificate_request_context) unpredictable to the client by randomly generating it. This prevents an attacker with temporary access to the client's private key from pre-computing valid CertificateVerify messages."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the certificate_request_context during post-handshake authentication, the client MUST handle it as received without any assumptions about its predictability."
        }
    }
}

