rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_group",
        "construction_rule": {
            "role": "client",
            "content": "When using (EC)DHE key establishment and sending a ClientHello following a HelloRetryRequest with a 'key_share' extension, the client MUST ensure that the NamedGroup in the 'key_share' extension matches the NamedGroup specified in the HelloRetryRequest."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello, the client MUST verify that the NamedGroup in the 'key_share' extension is the same as that received in the HelloRetryRequest. If the NamedGroup differs, the client MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

