        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When sending early data, the client MUST include the pre_shared_key extension in the ClientHello message to indicate its PSK identity for early data."
        },
        "processing_rule": {
            "role": "server",
            "content": "When accepting early_data, the server MUST process the client's ClientHello and immediately respond with its flight of messages, including ServerHello, without waiting for the client's EndOfEarlyData message."
        }
    }
}

