    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "server",
            "content": "When responding to a ClientHello with a HelloRetryRequest, the server must replace the original ClientHello (ClientHello1) with a special synthetic handshake message. This message must have the handshake type 'message_hash' and the contents set to Hash(ClientHello1)."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a HelloRetryRequest, the client must verify that the replaced ClientHello1 is a synthetic handshake message of the handshake type 'message_hash' and that its contents match Hash(ClientHello1). If this validation fails, the client must terminate the handshake with an appropriate alert."
        }
    }
}

