rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity",
        "construction_rule": {
            "role": "client",
            "content": "Each Pre Shared Key Extension in the ClientHello must associate a single Hash algorithm, as determined by the KDF Hash algorithm used in the connection where the session ticket was originally established for PSKs created via the ticket mechanism."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a Pre Shared Key Extension in ClientHello, the server must validate that each Pre-Shared Key is associated with a single Hash algorithm as determined by the KDF Hash algorithm from the connection where the session ticket was established for PSKs created via the ticket mechanism. If this validation fails, the handshake must be aborted and an 'illegal_parameter' alert must be sent."
        }
    }
}

