rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "If the server responds with a HelloRetryRequest, the client must compute the binder in tls.handshake.extensions.psk.binders for ClientHello2 over the concatenation of the following: a transcript of the partial ClientHello1 message (up to, but not including, the binders field) followed by the HelloRetryRequest message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello2 with the Pre-Shared Key extension after a HelloRetryRequest, the server must check that the binder value in tls.handshake.extensions.psk.binders has been computed correctly. If the binder is invalid, the server must terminate the connection with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to correctly compute the Pre-Shared Key (PSK) binder in the tls.handshake.extensions.psk.binders field of ClientHello2 after receiving a HelloRetryRequest, either by using an incorrect transcript or formatting the binder improperly.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
