rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "server",
            "content": "When the negotiated key exchange method requires certificate-based authentication (all methods except PSK), the server MUST construct and send the Certificate handshake message."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the Certificate handshake message, the client MUST validate the message to ensure that it aligns with the agreed-upon key exchange method. If the Certificate message is missing and certificates are required for authentication, the client MUST terminate the handshake with a handshake_failure alert."
        }
    }
}

