rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "server",
            "content": "When constructing a CertificateRequest message in TLS 1.3, the server MUST include the 'signature_algorithms' extension to list the signature algorithms it accepts for certificate signatures. Optionally, the server MAY also include the 'signature_algorithms_cert' extension for signature algorithms specific to certificate validation."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a CertificateRequest message in TLS 1.3, the client MUST verify the presence of the 'signature_algorithms' extension and validate the list of supported signature algorithms in 'tls.handshake.sig_hash_algs'. If the list is inconsistent with the client's supported algorithms, the client MUST abort the handshake with an appropriate alert."
        }
    }
}

