        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the ServerHello message, the client must expect the next message to be EncryptedExtensions and ensure it is encrypted with the server_handshake_traffic_secret. If EncryptedExtensions is not received immediately, it should consider the handshake to have failed."
        }
    }
}

