rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a PSK handshake flow (including 0-RTT) using the Pre-Shared Key Extension, the client MUST NOT include certificate-based client authentication in the handshake."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the server processes a PSK handshake flow (including 0-RTT) and detects certificate-based client authentication, the server MUST reject the handshake as non-compliant with the PSK handshake protocol."
        }
    }
}

