rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message with a pre_shared_key extension, the client MUST ensure that the ticket is not used if its age exceeds the ticket_lifetime value provided with the ticket."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a pre_shared_key extension, the server MUST verify that the obfuscated_ticket_age associated with any offered PSK identity does not exceed its corresponding ticket_lifetime. If it does, the server MUST NOT accept that PSK."
        }
    }
}

