text:
struct {
select (certificate_type) {
case RawPublicKey:
/* From RFC 7250 ASN.1_subjectPublicKeyInfo */
opaque ASN1_subjectPublicKeyInfo<1..2^24-1>;

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "When the certificate_type is RawPublicKey, the structure must include the ASN1_subjectPublicKeyInfo field as defined in RFC 7250. This field must be encoded with an opaque length of <1..2^24-1>, adhering to the specified format for RawPublicKey."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the certificate_type is RawPublicKey, the server must verify that the ASN1_subjectPublicKeyInfo field is present and properly formatted, with an opaque length in the range <1..2^24-1> as defined in RFC 7250. If this field is absent or malformed, the server must abort the handshake with an appropriate fatal error (e.g., handshake_failure)."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly format the ASN1_subjectPublicKeyInfo field when using RawPublicKey, either by omitting it entirely or providing an incorrect opaque length outside the range <1..2^24-1>.",
