        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a TLS ClientHello message with the ASN1_subjectPublicKeyInfo field having an opaque length of 2^24 (greater than 2^24-1).",
            "expected_behavior": "Alert"
