        "construction_rule": {
            "role": "client",
            "content": "The client MUST compute the Transcript-Hash as Hash(message_hash || 00 00 Hash.length || Hash(ClientHello1) || HelloRetryRequest || ... || Mn) prior to proceeding in the handshake. Each handshake message, when concatenated, must be included correctly in the computation with proper padding, as indicated."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving handshake messages, the server MUST verify that the Transcript-Hash matches the computation of Hash(message_hash || 00 00 Hash.length || Hash(ClientHello1) || HelloRetryRequest || ... || Mn). If the Transcript-Hash is not correctly computed, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

