rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "The client is permitted to stream 0-RTT data until it receives the server's Finished message. After receiving this, the client must send the EndOfEarlyData message, followed by the rest of the handshake."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving 0-RTT data from the client, the server must expect the EndOfEarlyData message following its Finished message. If the EndOfEarlyData message does not align with this sequence, the server must treat it as a protocol violation and abort the handshake with an 'unexpected_message' alert."
        }
    }
}

strategy:
