rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "When sending early data in TLS 1.3, the client may indicate support for early data with appropriate extensions, provided all checks are expected to pass."
        },
        "processing_rule": {
            "role": "server",
            "content": "If any checks for early data fail, the server MUST NOT respond with the 'Early Data Indication' extension. The server must discard all first-flight data and must fall back to 1-RTT or 2-RTT."
        }
    }
}

strategy:
{
    "rule_violation": "The client incorrectly includes the 'Early Data Indication' extension or sends malformed extensions while indicating support for early data, thereby failing to meet expected construction criteria.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with the 'Early Data Indication' extension containing an incorrectly set or invalid extension length (e.g., an overly large value).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message where the 'Early Data Indication' extension is included but is empty (length set to zero).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with the 'Early Data Indication' extension containing random or non-standard data outside the specified protocol requirements.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with multiple conflicting 'Early Data Indication' extensions.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message that includes the 'Early Data Indication' extension despite not supporting or negotiating early data.",
            "expected_behavior": "Alert"
        }
    ]
}

