rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "In the ClientHello message, the client MUST include the 'signature_algorithms' extension to indicate the supported authentication algorithms. This extension MUST contain a list of signature and hash algorithm pairs in the 'tls.handshake.sig_hash_algs' field."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST ensure that its end-entity certificate's public key and associated restrictions are compatible with one of the authentication algorithms listed in the client's 'signature_algorithms' extension in the 'tls.handshake.sig_hash_algs' field. If no compatible algorithm is found, the server MUST abort the handshake with a 'handshake_failure' alert."
        }
    }
}

