rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the CertificateVerify message, the client must include a signature over the transcript hash, computed as Transcript-Hash(Handshake Context with Certificate). This ensures the authenticity and integrity of the handshake."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the CertificateVerify message, the server must verify the signature over the Transcript-Hash(Handshake Context with Certificate). If the signature is invalid, the server must terminate the handshake with a 'decrypt_error' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly include a valid signature over the transcript hash (Transcript-Hash(Handshake Context with Certificate)) in the CertificateVerify message, violating the requirement for authenticity and integrity of the handshake.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with a corrupted signature (e.g., altering some bytes of the actual signature).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with a signature computed over an incorrect transcript hash (e.g., omitting the Certificate from the Handshake Context).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with an empty signature field (zero-length signature).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with a signature using a cryptographic algorithm that was not agreed upon during handshake negotiation.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message without the signature field entirely.",
            "expected_behavior": "Alert"
        }
    ]
}

