    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client/server",
            "content": "During the handshake phase in TLS 1.3, the Certificate, CertificateVerify, and Finished messages MUST be encrypted using keys derived from the [sender]_handshake_traffic_secret."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "Upon receipt of the Certificate, CertificateVerify, or Finished messages, the recipient MUST use keys derived from the [receiver]_handshake_traffic_secret to decrypt and verify the messages. If the decryption or verification fails, the handshake process MUST be terminated."
        }
    }
}

