rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.obfuscated_ticket_age",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Pre Shared Key Extension in ClientHello, the client MUST compute the 'obfuscated_ticket_age' field for each PskIdentity by taking the age of the ticket in milliseconds and adding the value of 'ticket_age_add' (associated with the ticket), modulo 2^32."
        },
        "processing_rule": {
            "role": "server",
            "content": "When processing the Pre Shared Key Extension in ClientHello, the server MUST verify that the 'obfuscated_ticket_age' field of each PskIdentity is correctly formed by taking the difference between the provided 'obfuscated_ticket_age' and 'ticket_age_add' modulo 2^32 to determine the original ticket age (in milliseconds). If the calculation fails, the associated identity must be considered invalid."
        }
    }
}

strategy:
{
