            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Simulate a handshake where the server omits the Finished message, after sending all other required messages.",
            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Complete a handshake up to the Certificate message, then abruptly close connection without sending Finished message.",
