        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Intentionally send an incomplete Finished message from client, leading to no authentication confirmation.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Intentionally send an incomplete Finished message from server, leading to no authentication confirmation.",
            "expected_behavior": "Alert"
        }
    ]
}

