rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "If a CertificateRequest message is sent with a non-empty 'oid_filters' extension, the client must construct its end-entity certificate to include extension OIDs that match those recognized and supported by the server."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receipt of the end-entity certificate, the server must verify that the certificate matches the OIDs specified in the 'oid_filters' extension, if present in the CertificateRequest. If the OIDs do not match, the server must reject the certificate as non-compliant with the client's OID filters."
        }
    }
}

