    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When sending the Signature Algorithms extension, the client MAY include algorithms for signing self-signed certificates or certificates expected to be trust anchors without validation requirements."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms extension, the server MUST process the list of signature algorithms and note that certificates which are self-signed or expected to be trust anchors are allowed to be signed with any algorithm and are not part of the validation chain."
        }
    }
}

