    "rule_violation": "The client improperly includes unsupported or malformed signature algorithms in the Signature Algorithms extension, which do not align with those permitted for self-signed certificates or expected trust anchors.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms extension including an unsupported signature algorithm '0xAAAA'.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms extension including a malformed entry with incomplete length field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms extension containing duplicated entries for a signature algorithm '0x0403'.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When sending the Signature Algorithms extension, the client MAY include algorithms for signing self-signed certificates or certificates expected to be trust anchors without validation requirements."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms extension, the server MUST process the list of signature algorithms and note that certificates which are self-signed or expected to be trust anchors are allowed to be signed with any algorithm and are not part of the validation chain."
        }
    }
}

