rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the CertificateVerify message, the client must compute the signature field using the content covered by the digital signature and the private signing key corresponding to the certificate sent in the previous message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the CertificateVerify message, the server must verify the correctness of the signature field using the client's public key from the certificate sent earlier. If validation fails, the server must abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to compute the signature field of the CertificateVerify message correctly, either by using the wrong content or an incorrect signing key.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with a signature computed using the wrong private key not corresponding to the certificate sent earlier.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with a signature field populated with random data instead of a valid signature.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with the signature computed over incorrect content that is not the content covered by the digital signature.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a CertificateVerify message with an empty signature field.",
            "expected_behavior": "Alert"
        }
    ]
}

