rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "server",
            "content": "When the server sends a Certificate message, it must ensure the message is not empty. An empty Certificate message is considered invalid in TLS 1.3."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a Certificate message, if the client detects that the message is empty, it MUST abort the handshake and send a 'decode_error' alert in accordance with TLS 1.3 specifications."
        }
    }
}

strategy:
{
    "rule_violation": "The server violates the rule by sending an empty Certificate message, which is considered invalid in TLS 1.3.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate message with no certificates included (completely empty payload).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate message with an incorrect length field indicating the presence of certificates, but without including any certificate data.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate message containing only a blank certificate chain field, without including any certificates.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate message with malformed data that results in an empty certificate message upon parsing.",
            "expected_behavior": "Alert"
        }
    ]
}

