rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "server",
            "content": "If the 'server_certificate_type' or 'client_certificate_type' extension was not negotiated in EncryptedExtensions, the server MAY omit a certificate that specifies a trust anchor from the certificate chain, provided that supported peers are known to possess any omitted certificates."
        },
        "processing_rule": {
            "role": "client",
            "content": "The client MUST be prepared to receive a certificate chain in which the certificate specifying a trust anchor is omitted, if the 'server_certificate_type' or 'client_certificate_type' extension was not negotiated in EncryptedExtensions, and the client is expected to validate the chain based on locally configured trust anchors."
        }
    }
}

strategy:
{
    "rule_violation": "The server fails to properly construct the certificate chain by either including a trust anchor when it should be omitted, or omitting it when it should be included, based on the negotiation of 'server_certificate_type' or 'client_certificate_type' extension.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a certificate chain including a trust anchor even though 'server_certificate_type' or 'client_certificate_type' was not negotiated in EncryptedExtensions, where it should have been omitted.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Omit the trust anchor from the certificate chain even though 'server_certificate_type' or 'client_certificate_type' was negotiated in EncryptedExtensions, where it should not have been omitted.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a malformed certificate chain with incorrect total length in the extensions, causing unexpected parsing behavior.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send an empty certificate chain without any certificates included, violating the expectation of receiving a valid chain.",
            "expected_behavior": "Alert"
        }
    ]
}

