rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the 'signature_algorithms' or 'signature_algorithms_cert' extension in the ClientHello, the client MUST indicate the supported signature schemes. The certificate used must permit the key to be used for signing, and the digitalSignature bit in the Key Usage extension MUST be set if the Key Usage extension is present."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the 'signature_algorithms' or 'signature_algorithms_cert' extension, the server MUST validate that the certificate's key usage settings allow signing (ensuring the digitalSignature bit is set if the Key Usage extension is present). The server MUST ensure that the selected signature scheme aligns with one of the client's supported schemes from 'tls.handshake.sig_hash_algs'."
        }
    }
}

strategy:
{
    "rule_violation": "The client does not properly construct the 'signature_algorithms' or 'signature_algorithms_cert' extension in the ClientHello, either by omitting supported signature schemes, not setting the digitalSignature bit in the Key Usage extension when present, or indicating unsupported or invalid signature schemes.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
