rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message, the client MUST specify the signature algorithm used in the 'tls.handshake.sig_hash_algs' field. The algorithm must be used to perform a digital signature covering the hash output as described in Section 4.4.1."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST verify that the 'tls.handshake.sig_hash_algs' field specifies a signature algorithm. The content covered under the signature must match the hash output as detailed in Section 4.4.1. If the algorithm is not specified or if the signature does not cover the correct content, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

