            "content": "When constructing a CertificateRequest message, if the 'certificate_authorities' extension is included, then the server SHOULD ensure that at least one certificate in the certificate chain is issued by the listed Certificate Authorities (CAs)."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a CertificateRequest message, the client SHOULD check that at least one certificate in the certificate chain was issued by one of the CAs listed in the 'certificate_authorities' extension. If not, the client SHOULD consider the certificate chain as potentially invalid."
        }
    }
}

