rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the handshake message, the client MUST include a certificate of type X.509v3 [RFC5280] in 'tls.handshake.ciphersuites', unless an alternative certificate type has been explicitly negotiated (e.g., [RFC7250])."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the handshake message, the server MUST verify that the certificate type included in 'tls.handshake.ciphersuites' is X.509v3 [RFC5280] unless an alternative certificate type was explicitly negotiated. If the certificate type is different and not explicitly negotiated, the server MUST abort the handshake and respond with an 'unsupported_certificate' alert."
        }
    }
}

