rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When a client sends the CertificateVerify message, the signature algorithm used in the signature MUST be one of those listed in the 'tls.handshake.sig_hash_algs' field of the 'signature_algorithms' extension included in the CertificateRequest message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a CertificateVerify message from the client, the server MUST verify that the signature algorithm used is present in the 'tls.handshake.sig_hash_algs' field of the 'signature_algorithms' extension that was previously conveyed in its CertificateRequest message. If the algorithm is not present, the server MUST reject the certificate verification process."
        }
    }
}

