rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.verify_data",
        "construction_rule": {
            "role": "client/server",
            "content": "The verify_data field must be computed as: verify_data = HMAC(finished_key, Transcript-Hash(Handshake Context, Certificate*, CertificateVerify*)) and included in the handshake message only if the relevant components (Handshake Context, Certificate*, CertificateVerify*) are present."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "Upon receiving the handshake message, the recipient (client/server) MUST verify the correctness of the verify_data value by independently computing: verify_data = HMAC(finished_key, Transcript-Hash(Handshake Context, Certificate*, CertificateVerify*)). If the computed value does not match the received verify_data, the handshake must be terminated with an error."
        }
    }
}

strategy:
{
