            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.verify_data",
            "description": "Send a handshake message with verify_data computed using an incorrect finished_key.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.verify_data",
            "description": "Send a handshake message with verify_data computed using an incorrect Transcript-Hash that does not incorporate all necessary handshake messages.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.verify_data",
            "description": "Send a handshake message with verify_data deliberately altered to deviate from the correct calculation.",
            "expected_behavior": "Alert"
        }
    ]
}

