rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Signature Algorithms extension in ClientHello, the client MUST include only valid signature algorithms. SHA-1 signature algorithms are only permitted for use in legacy certificates and MUST NOT be included as valid options for CertificateVerify signatures."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Signature Algorithms extension in ClientHello, the server MUST validate the included signature algorithms. If any SHA-1 signature algorithms are present, the server MUST ensure they are used solely for legacy certificates and reject their use for CertificateVerify signatures."
        }
    }
}

