rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "server",
            "content": "Any record sent by the server after a Finished message MUST be encrypted under the appropriate application traffic key, as specified in Section 7.2 of the protocol. This requirement includes alerts sent in response to client Certificate and CertificateVerify messages."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "The receiver MUST validate that records following a Finished message are encrypted using the appropriate application traffic key. If a record is not properly encrypted, the record MUST be rejected, and the connection SHOULD be terminated."
        }
    }
}

