        "construction_rule": {
            "role": "client/server",
            "content": "Once a Finished message is sent and the Finished message from the peer is received and validated, the content type for subsequent records carrying application data MUST be set to 0x17 (Application Data)."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "The implementation MUST ensure that Application Data is neither sent nor processed until the Finished message has been sent, and the peer's Finished message has been received and validated. If an application data record is processed beforehand, the connection MUST be terminated with a 'unexpected_message' alert."
        }
    }
}

