rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "server",
            "content": "In the Certificate Verify message, server MUST only include RSASSA-PSS algorithms in rsa signatures, even if RSASSA-PKCS1-v1_5 algorithms are listed in 'signature_algorithms'."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the Certificate Verify message, client MUST verify that RSASSA-PSS algorithm is used for rsa signatures, ignoring any RSASSA-PKCS1-v1_5 algorithms that may appear in 'signature_algorithms'. If RSASSA-PSS is not used, the client must abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The server includes RSASSA-PKCS1-v1_5 algorithms in the Certificate Verify message for RSA signatures, violating the requirement to use only RSASSA-PSS algorithms.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a Certificate Verify message with RSA signatures using the RSASSA-PKCS1-v1_5 algorithm, instead of the required RSASSA-PSS.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Include both RSASSA-PSS and RSASSA-PKCS1-v1_5 algorithms in the Certificate Verify message, but use RSASSA-PKCS1-v1_5 for the actual signature.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a Certificate Verify message using an invalid or unsupported signature algorithm for RSA signatures.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Exclude the RSASSA-PSS algorithms entirely from the Certificate Verify message for RSA signatures.",
            "expected_behavior": "Alert"
        }
    ]
}

