rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "In ClientHello messages, the client MUST correctly encode the extensions_length field, which includes all recognized extensions."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving the ServerHello or other relevant handshake messages, the client MUST process recognized extensions and MUST ignore any unrecognized extensions without aborting the handshake."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to correctly encode the extensions_length field in the ClientHello message, causing it to either contain incorrect values or fail to reflect the total length of extensions.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
