            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with the extensions_length field set to a value larger than the actual length of the extensions (e.g., extensions_length set to 30 while the actual length is 20).",
