        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with a malformed extensions_length field (e.g., containing non-numeric or corrupted data).",
            "expected_behavior": "Alert"
        }
    ]
}

