rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Ec Point Formats Extension",
        "field": "tls.handshake.extensions_ec_point_formats",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing a handshake message, the sender MUST NOT include the Ec Point Formats Extension in the response unless the remote endpoint sent a corresponding extension request. An exception is allowed for the 'cookie' extension in HelloRetryRequest."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving an Ec Point Formats Extension, the endpoint MUST verify that a corresponding extension request was sent earlier. If no such request was sent (apart from the case of the 'cookie' extension in HelloRetryRequest), the receiver MUST abort the handshake with an 'unsupported_extension' alert."
        }
    }
}

