rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the ClientHello message, the client must include cipher suites it supports, allowing the server to choose an appropriate certificate. This selection influences the server's certificate choice based on server-side criteria like transport layer endpoint and configuration."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server must select an appropriate certificate from its available options based on criteria such as supported cipher suites, transport-layer endpoint, local configuration, and preferences."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly list supported cipher suites in the ClientHello message, which may influence the server's ability to select an appropriate certificate.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with an empty cipher suites list (zero length).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with a cipher suites list containing only unsupported or invalid ciphers.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with an unusually large number of cipher suites, exceeding typical limits.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with duplicate cipher suite entries in the list.",
            "expected_behavior": "Alert"
        }
    ]
}

