            "content": "When constructing a response, the sender MUST NOT include the Signature Algorithms Extension unless the remote endpoint has explicitly requested it through the corresponding extension. The exception is the 'cookie' extension in the HelloRetryRequest, which may be sent independently."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a Signature Algorithms Extension response that was not explicitly requested by the receiver, the receiver MUST abort the handshake and send an 'unsupported_extension' alert as per the protocol requirements."
        }
    }
}

