        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "sender",
            "content": "In the Certificate Verify message, the sender must ensure that the signature algorithm used is compatible with the key in the sender's end-entity certificate."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon processing the Certificate Verify message, the receiver must verify that the signature algorithm used is compatible with the key in the sender's end-entity certificate. If not, the handshake must be terminated with a 'handshake_failure' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The sender uses a signature algorithm in the Certificate Verify message that is incompatible with the key in the sender's end-entity certificate.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate Verify message using an RSA key while specifying the signature algorithm as 'ecdsa_secp256r1_sha256', which is incompatible with the key type.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate Verify message using an ECDSA key while specifying the signature algorithm as 'rsa_pss_rsae_sha256', which is incompatible with the key type.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate Verify message using an Ed25519 key while specifying the signature algorithm as 'rsa_pss_rsae_sha512', which is incompatible with the key type.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate Verify message omitting the signature algorithm field entirely, making it impossible to validate compatibility with the sender's certificate.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.type",
            "description": "Send a Certificate Verify message using a DSA key (deprecated) with a signature algorithm from an unsupported or incompatible group.",
            "expected_behavior": "Alert"
        }
    ]
}

