    "rule_violation": "The server includes the Server Name Extension in the ServerHello message even though the client did not include it in the ClientHello request, violating the protocol's conditions for extension handling.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Server Name Extension",
            "field": "Extension: server_name",
            "description": "Send a ClientHello message without the Server Name Extension and receive a ServerHello response containing the Server Name Extension.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Server Name Extension",
            "field": "Extension: server_name",
            "description": "Send a ClientHello message with no extensions, and receive a ServerHello response that incorrectly includes the Server Name Extension.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Server Name Extension",
            "field": "Extension: server_name",
            "description": "Send a ClientHello message with unrelated extensions (excluding the Server Name Extension), and receive a ServerHello response with the Server Name Extension erroneously added.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Server Name Extension",
        "field": "Extension: server_name",
        "construction_rule": {
            "role": "server",
            "content": "The server MUST NOT send the Server Name Extension in ServerHello if the client did not include the Server Name Extension in the ClientHello request, except for the 'cookie' extension in HelloRetryRequest."
        },
        "processing_rule": {
            "role": "endpoint",
            "content": "If an endpoint receives a Server Name Extension without having sent the corresponding request, it MUST abort the handshake with an 'unsupported_extension' alert, unless it's a 'cookie' extension in the HelloRetryRequest."
        }
    }
}

