rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "sender",
            "content": "The sender must fragment information blocks into TLSPlaintext records such that each record's 'tls.record.length' field is set to 2^14 bytes (16384 bytes) or less."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a TLSPlaintext record, the receiver must verify that the 'tls.record.length' does not exceed 2^14 bytes (16384 bytes). If the length exceeds this limit, the receiver must reject the record and abort the connection with an error."
        }
    }
}

strategy:
{
    "rule_violation": "The sender creates TLSPlaintext records with a 'tls.record.length' field that exceeds 2^14 bytes (16384 bytes), violating the maximum length requirement.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSPlaintext record with the 'tls.record.length' field set to 16385 bytes (1 byte over the maximum limit).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSPlaintext record with the 'tls.record.length' field set to 20000 bytes (6156 bytes over the maximum limit).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSPlaintext record with the 'tls.record.length' field set to 32768 bytes (twice the maximum limit).",
            "expected_behavior": "Alert"
        }
    ]
}

