rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client/server",
            "content": "When constructing a handshake message, endpoints MAY include support for MD5 and SHA-1 algorithms for certificates that are self-signed or trust anchors, provided they meet local policy requirements and are necessary in the trust chain."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "Upon receiving certificates that use MD5 or SHA-1 algorithms and are self-signed or trust anchors, endpoints MAY accept them only if they meet local policy requirements. Otherwise, the handshake must proceed without relying on those certificates."
        }
    }
}

