rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "When constructing Application Data messages in TLS 1.3, client must ensure that data is encapsulated within records with tls.record content type set to Application Data. The data must be protected using the negotiated encryption and integrity mechanisms. Zero-length fragments may be sent and data may be split across multiple records or combined into a single record."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving Application Data messages, the server must verify that the record is using the correct protection mechanisms. Zero-length fragments must be accepted, and the server should handle data that is split across multiple records or combined into a single record."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to encapsulate application data within records with the correct tls.record content type or does not use the appropriate encryption and integrity mechanisms, violating TLS 1.3 requirements.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send an Application Data message with the tls.record content type set to an incorrect type, such as handshake.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send an Application Data message without applying any encryption or integrity protection.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send an Application Data message with incorrect encryption parameters inconsistent with the negotiated ciphersuite.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a zero-length Application Data message with an incorrect tls.record content type.",
            "expected_behavior": "Alert"
        }
    ]
}

