        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving ClientHello with 'post_handshake_auth' extension, the server MAY request client authentication anytime after handshake completion by sending a CertificateRequest message. The client MUST respond with the appropriate Authentication messages."
        }
    }
}

