rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST ensure that all its handshake messages for a given response appear consecutively on the wire. No handshake message from the client should be interrupted by messages of other types."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST validate that all client handshake messages for a given response are received consecutively. If interruptions are detected in the sequence, the server MUST treat this as a protocol error and react accordingly."
        }
    }
}

