rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "The TLS record protocol on the client-side must fragment outgoing messages into manageable blocks, apply necessary protection (e.g., encryption, integrity), and transmit them to the server."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving TLS records, the server must verify the data for integrity, decrypt it if necessary, reassemble it if fragmented, and deliver it to higher-level clients. If any verification fails, the server must discard the message and handle the error as per protocol specifications."
        }
    }
}

strategy:
{
    "rule_violation": "The client violates the fragmentation or protection requirements of the TLS record protocol by either failing to fragment messages properly, sending messages without applying necessary protection, or exceeding the maximum allowable size.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record that exceeds the maximum allowable size of 16,384 bytes.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record without applying encryption to the payload, leaving it in plaintext.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a fragmented TLS record where the reassembled data size does not match the original data due to tampered offsets or lengths.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record with an incorrect MAC (Message Authentication Code), violating the integrity protection requirements.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record with a malformed structure, such as overlapping fragments or extra padding bytes.",
            "expected_behavior": "Alert"
        }
    ]
}

