rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client and server",
            "content": "If either side initiates a KeyUpdate with request_update set to 'update_requested', it must send a KeyUpdate message. If KeyUpdates cross in flight, both sides must ensure they send a response, leading to an increment of two generations."
        },
        "processing_rule": {
            "role": "client and server",
            "content": "Upon receiving a KeyUpdate with request_update set to 'update_requested', the receiving side must also send a KeyUpdate response. If KeyUpdates cross in flight, both sides must reconcile by incrementing by two generations to maintain synchrony."
        }
    }
}

strategy:
{
    "rule_violation": "Failure to properly handle simultaneous KeyUpdate messages, which results in errors in generation increment or not sending a required KeyUpdate response.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a KeyUpdate message with 'update_requested' and fail to send a KeyUpdate response upon receiving an 'update_requested' from the peer.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Simultaneously send a KeyUpdate message with 'update_requested' and discard the received KeyUpdate from the peer without incrementing the generation counter.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send two consecutive KeyUpdate messages with 'update_requested' without cross-checking for the expected response from the peer.",
            "expected_behavior": "Alert"
        }
    ]
}

