    "rule_violation": "The server sets the legacy_record_version field to a value other than 0x0303 or 0x0301 for records generated by a TLS 1.3 server implementation.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.version",
            "description": "Send a TLS record with the legacy_record_version field set to an invalid value 0x0200",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.version",
            "description": "Send a TLS record with the legacy_record_version field set to an invalid value 0x0000",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.version",
            "description": "Send a TLS record with the legacy_record_version field set to an invalid value 0x0400",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.version",
            "description": "Send a TLS record with the legacy_record_version field set to 0x0302",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.version",
        "construction_rule": {
            "role": "server",
            "content": "For all records generated by a TLS 1.3 server implementation, except an initial ClientHello not generated after a HelloRetryRequest, the server MUST set the legacy_record_version field to 0x0303. Optionally, the field MAY be set to 0x0301 for compatibility purposes."
        },
        "processing_rule": {
            "role": "client",
            "content": "The client MUST accept the legacy_record_version field set to either 0x0303 or 0x0301 on records other than the initial ClientHello."
        }
    }
}

