rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "sender",
            "content": "When sending a record in TLS 1.3, the sender MUST ensure that the length of TLSCiphertext.encrypted_record does not exceed 2^14 + 256 bytes."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "When receiving a record in TLS 1.3, the receiver MUST verify that the length of TLSCiphertext.encrypted_record does not exceed 2^14 + 256 bytes. If the length exceeds this limit, the receiver MUST terminate the connection with a 'record_overflow' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The sender transmits a TLSCiphertext.encrypted_record with a length exceeding the maximum limit of 2^14 + 256 bytes, violating the length restriction for TLSCiphertext records.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a record with a TLSCiphertext.encrypted_record length of 2^14 + 257 bytes, exceeding the maximum allowed length by 1 byte.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a record with a TLSCiphertext.encrypted_record length of 2^14 + 300 bytes, exceeding the maximum allowed length by 44 bytes.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a record with a TLSCiphertext.encrypted_record length of 2^14 + 500 bytes, exceeding the maximum allowed length by 244 bytes.",
            "expected_behavior": "Alert"
        }
    ]
}

