rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.version",
        "construction_rule": {
            "role": "client",
            "content": "When sending a second ClientHello in TLS 1.3, client MUST set the tls.record.version field to 0x0303 (TLS 1.2) to ensure compatibility."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a second ClientHello or ServerHello, the server MUST verify that the tls.record.version is 0x0303. If it is not, the server MUST terminate the connection with a protocol_version alert."
        }
    }
}

strategy:
