rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "When sending ClientHello in TLS 1.3, the client MUST include the cipher suites in the 'tls.handshake.ciphersuites' field, indicating support for AEAD algorithms for encryption and integrity."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST use the provided 'tls.handshake.ciphersuites' to select a compatible AEAD cipher. The server then uses the cipher key, nonce, additional data, and AEADEncrypted value to decrypt and verify, producing either plaintext or an error without a separate integrity check."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly include AEAD cipher suites in the 'tls.handshake.ciphersuites' field, either by omitting them entirely or by including non-AEAD cipher suites.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with an empty 'tls.handshake.ciphersuites' field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with the 'tls.handshake.ciphersuites' field containing only non-AEAD cipher suites.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with the 'tls.handshake.ciphersuites' field containing unsupported or deprecated cipher suites.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with corrupted data in the 'tls.handshake.ciphersuites' field, including random bytes.",
            "expected_behavior": "Alert"
        }
    ]
}

