        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST ensure each TLSPlaintext record with content type 'Alert' is not fragmented and contains exactly one Alert message within the TLS 1.3 protocol."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a TLSPlaintext record with content type 'Alert', the server MUST verify the record contains precisely one Alert message and is not a result of coalescing. If the record does not comply, the server must treat it as invalid according to TLS 1.3 processing rules."
        }
    }
}

