    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "client",
            "content": "If the server sent an 'early_data' extension in EncryptedExtensions, the client MUST construct and send an EndOfEarlyData message after receiving the server Finished message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the EndOfEarlyData message, the server MUST ensure it is only present if the 'early_data' extension was sent in EncryptedExtensions. If it is sent without prior 'early_data' extension, the server MUST terminate the connection with an 'unexpected_message' alert."
        }
    }
}

