rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "When encrypting data with an AEAD algorithm in TLS 1.3, the client MUST ensure that the resulting ciphertext does not expand by more than 255 octets compared to the plaintext."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving encrypted data, the server MUST verify that the expansion caused by the AEAD algorithm does not exceed 255 octets. If it exceeds, the server MUST treat it as a malformed message and reject it."
        }
    }
}

