rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "The client must encrypt the 'No Extension' message using keys derived from the 'client_early_traffic_secret' before constructing the message to ensure confidentiality."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the 'No Extension' message, the server must decrypt it using keys derived from the 'client_early_traffic_secret'. If decryption fails, the server must terminate the connection with an appropriate error alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client sends the 'No Extension' message unencrypted or with incorrect encryption keys, violating the requirement for confidentiality using 'client_early_traffic_secret'.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send the 'No Extension' message without encrypting it, directly in plaintext.",
