rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "When sending a KeyUpdate message, the sender MUST encrypt the message with the old keys before transitioning to new keys."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "The receiver MUST ensure that a KeyUpdate message received is encrypted with the old keys and MUST process it before accepting any messages encrypted with the new keys. Failure to enforce this may lead to message truncation attacks."
        }
    }
}

strategy:
{
