            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a KeyUpdate message without applying encryption to the message.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a KeyUpdate message encrypted with partially updated keys where one direction uses new keys while the other uses old keys.",
            "expected_behavior": "Alert"
        }
    ]
}

