rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "During a TLS 1.3 handshake, the client must ensure that all handshake messages such as ClientHello, EndOfEarlyData, ServerHello, Finished, and KeyUpdate are aligned with a record boundary. These messages must not span key changes."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must verify that handshake messages do not span key changes and are aligned with record boundaries. If a message preceding a key change does not align with a record boundary, the server must terminate the connection and send an 'unexpected_message' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client sends handshake messages that are not aligned with record boundaries, spanning a key change, violating the requirement for proper alignment.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a ClientHello message that begins in one record and ends in another record, crossing a key change boundary.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send an EndOfEarlyData message that does not align with a record boundary, overlapping a key change.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a Finished message split across two records with one side of the boundary occurring before a key change and the other after.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a ServerHello message fragmented across records, with fragments sent both before and after a key change.",
            "expected_behavior": "Alert"
        }
    ]
}

