rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "sender",
            "content": "A sender peer that has already sent a Finished message MUST construct a KeyUpdate handshake message when it intends to update its cryptographic keys. The sender MUST indicate the handshake type as 'KeyUpdate' in tls.handshake.type."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "A receiver peer, upon receiving a KeyUpdate handshake message, MUST verify that the sender peer has already sent a Finished message. If this condition is not met, the receiver MUST terminate the connection. Otherwise, the KeyUpdate message MUST be processed to update the cryptographic keys."
        }
    }
}

