rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "sender",
            "content": "A TLS implementation must ensure that the sequence number never wraps during communication. If the maximum sequence number of 2^64-1 is reached, the sender MUST either rekey or terminate the connection to prevent sequence number wrapping."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "If a sequence number wrap occurs during communication, the receiver MUST either rekey or terminate the connection to ensure protocol security."
        }
    }
}

