rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "The client MAY use the PSK for future handshakes by including the ticket value in the 'tls.handshake.extensions.psk.identity.identity' field within the 'pre_shared_key' extension in the ClientHello."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server MUST process the 'tls.handshake.extensions.psk.identity.identity' field within the 'pre_shared_key' extension to identify the PSK. If the PSK is valid, the server proceeds with the resumption handshake; otherwise, the server MUST ignore the PSK and proceed with a full handshake."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes invalid, malformed, or absent ticket values in the 'tls.handshake.extensions.psk.identity.identity' field of the pre_shared_key extension in the ClientHello, resulting in a violation of the construction rule.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello with the 'tls.handshake.extensions.psk.identity.identity' field containing an invalid ticket value (e.g., a string with random bytes or a ticket value from a different context).",
            "expected_behavior": "ServerHello"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello with the 'tls.handshake.extensions.psk.identity.identity' field completely omitted, leaving the pre_shared_key extension present but without an identity field.",
            "expected_behavior": "ServerHello"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello with the 'tls.handshake.extensions.psk.identity.identity' field containing a malformed structure, such as an invalid length prefix or corrupted data.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello with the 'tls.handshake.extensions.psk.identity.identity' field containing a valid format but referencing a PSK that does not match any the server has stored.",
            "expected_behavior": "ServerHello"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello where the 'tls.handshake.extensions.psk.identity.identity' field contains mixed values, such as one valid ticket and one invalid ticket in the list of PSKs.",
            "expected_behavior": "ServerHello"
        }
    ]
}

