rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing a TLSCiphertext record, sender MUST set the outer 'tls.record.content_type' field to 23 (application_data) to maintain compatibility with middleboxes accustomed to previous versions of TLS."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a TLSCiphertext record, receiver MUST ignore the outer 'tls.record.content_type' field and determine the actual content type of the record from 'TLSInnerPlaintext.type' after decryption."
        }
    }
}

