rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "sender",
            "content": "When deriving send and receive keys from traffic secrets, the sender MUST ensure the send keys are derived from a unique traffic secret to maintain forward secrecy."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "The receiver MUST ensure that the receive traffic secret is derived from a unique, independent source from the sender's traffic secret. Retaining the receive traffic secret MUST NOT compromise the forward secrecy of data sent prior to the sender's key update."
        }
    }
}

strategy:
