    "rule_violation": "The server fails to handle out-of-order messages or delayed responses to the CertificateRequest, violating the requirement to process arbitrary messages in accordance with their type and the protocol state.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send several out-of-order application data messages from the client after receiving the CertificateRequest but before responding to it with a Certificate message.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send an incorrectly structured handshake message (e.g., a malformed Finished message) from the client immediately after the CertificateRequest is sent, before a proper Certificate response.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Delay the client’s Certificate response for an extended period, while sending valid encrypted application data messages in the meantime.",
            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send an invalid handshake message (e.g., a ClientHello message) after the CertificateRequest is sent but before the client provides a Certificate response.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "After sending a KeyUpdate message, the sender MUST ensure that all subsequent traffic is encrypted using the next generation of keys, as specified in Section 7.2."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a KeyUpdate message, the receiver must expect that subsequent messages are encrypted using the updated keys and must decrypt them accordingly."
        }
    }
}

strategy:
{
    "rule_violation": "The sender fails to ensure that all subsequent traffic after sending a KeyUpdate message is encrypted using the updated generation of keys, violating the construction rule for secure communication.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a KeyUpdate message but continue encrypting subsequent traffic using the old generation of keys.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a KeyUpdate message followed by an unencrypted plaintext application data record.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a KeyUpdate message followed by an application data record encrypted with mismatched keys from a different key generation.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Skip sending a KeyUpdate message but proceed to encrypt subsequent traffic with a new key generation.",
            "expected_behavior": "Alert"
        }
    ]
}

