rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client/server",
            "content": "For each new connection and whenever the key is changed, the client/server must initialize the sequence number to zero before sending the first record, which will use sequence number 0. After writing each record, the sequence number must be incremented by one."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "For each new connection and whenever the key is changed, the client/server must initialize the sequence number to zero before processing the first incoming record, which should have sequence number 0. After reading each record, the sequence number must be incremented by one."
        }
    }
}

strategy:
{
   "rule_violation": "The client/server violates the requirement to correctly handle the sequence number by improperly initializing it or incrementing it in replay-protection mechanisms.",
   "testing_strategies": [
       {
           "protocol": "TLS 1.3",
           "message": "No Extension",
           "field": "tls.record",
           "description": "Send a TLS record with a sequence number that is not set to zero (e.g., set to 1) at the beginning of a new connection.",
           "expected_behavior": "Alert"
       },
       {
           "protocol": "TLS 1.3",
           "message": "No Extension",
           "field": "tls.record",
           "description": "Send a TLS record with a sequence number that skips a number (e.g., send sequence number 0, then sequence number 2, omitting sequence number 1).",
           "expected_behavior": "Alert"
       },
       {
           "protocol": "TLS 1.3",
           "message": "No Extension",
           "field": "tls.record",
           "description": "Send a TLS record with a sequence number that decreases (e.g., first send sequence number 1, then send sequence number 0).",
           "expected_behavior": "Alert"
       },
       {
           "protocol": "TLS 1.3",
           "message": "No Extension",
           "field": "tls.record",
           "description": "Send a duplicate TLS record with the same sequence number (e.g., send the same record with sequence number 1 twice).",
           "expected_behavior": "Alert"
       }
   ]
}

