rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "Extension: pre_shared_key",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message with multiple extensions, the client MUST ensure that the Pre Shared Key Extension is the last extension included in the message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server MUST verify that if the Pre Shared Key Extension is present, it is the last extension. If it is not the last, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes the Pre Shared Key Extension in the ClientHello message, but it is not the last extension in the message.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "Extension: pre_shared_key",
            "description": "Send a ClientHello message where the Pre Shared Key Extension is followed by another extension, such as Supported Versions.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "Extension: pre_shared_key",
            "description": "Send a ClientHello message where the Pre Shared Key Extension is placed in the middle of the list of included extensions.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "Extension: pre_shared_key",
            "description": "Send a ClientHello message with the Pre Shared Key Extension listed first, followed by other extensions.",
            "expected_behavior": "Alert"
        }
    ]
}

