rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a TLSInnerPlaintext message, the client MUST ensure the total length, including content type and padding, does not exceed 2^14 + 1 octets. If the record_size_limit extension reduces the maximum fragment length, the reduced limit must apply."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST validate that the received TLSInnerPlaintext length does not exceed 2^14 + 1 octets. If the record_size_limit extension is in use, the length must adhere to the reduced limit. Exceeding these limits should result in terminating the connection with a record_overflow alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client constructs a TLSInnerPlaintext message where the total length exceeds 2^14 + 1 octets or the reduced limit set by the record_size_limit extension, violating the length constraints.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSInnerPlaintext message with total length 2^14 + 2 octets, exceeding the maximum allowed limit by one octet.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSInnerPlaintext message with total length 2^15 octets, greatly exceeding the maximum allowed limit.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSInnerPlaintext message with reduced record_size_limit extension set to 1024 octets, but with a total length of 1025 octets.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLSInnerPlaintext message with reduced record_size_limit extension set to 512 octets, but with a total length of 600 octets.",
            "expected_behavior": "Alert"
        }
    ]
}

