rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "A client MAY coalesce multiple Handshake messages into a single TLSPlaintext record or fragment them over multiple records, as long as Handshake messages are not interleaved with other record types. If splitting a Handshake message across records, the split parts MUST be contiguous."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST process Handshake messages without interleaving them with other types of records. If a Handshake message is fragmented across multiple records, the fragments must appear sequentially without any intervening records of different types."
        }
    }
}

strategy:
{
    "rule_violation": "The client interleaves Handshake messages with other record types or fragments Handshake messages in a non-contiguous manner, violating the construction and processing rules.",
