            "description": "Send a TLSPlaintext record stream where a Handshake message is split between two records, but another record type (e.g., ApplicationData) is placed in between the Handshake message fragments.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLSPlaintext record containing an incomplete Handshake message, followed by a record with an entirely different record type (e.g., ChangeCipherSpec), and then continue the Handshake message in a subsequent record.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLSPlaintext record containing multiple Handshake messages interleaved with other types of records (e.g., Alert) within the same stream.",
