        },
        "processing_rule": {
            "role": "receiver",
            "content": "Receiver MUST check that received Application Data records are protected. If any unprotected Application Data is detected, the receiver MUST terminate the connection immediately."
        }
    }
}

strategy:
{
    "rule_violation": "The sender fails to ensure that all Application Data records are encrypted, and transmits unprotected Application Data records on the wire.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an unprotected Application Data record with content_type set to 0x17 (Application Data) and data in plaintext.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an unencrypted Application Data record mixed within an otherwise encrypted TLS 1.3 session.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a fragmented unprotected Application Data record with content_type set to 0x17, ensuring it is split across multiple TCP packets.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an Application Data record with incorrect encryption (e.g., using a random key or no key instead of the session key).",
            "expected_behavior": "Alert"
        }
    ]
}

