rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "When configuring TLS 1.3 ciphersuites, client MUST NOT include any AEAD algorithm where N_MAX is less than 8 bytes."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, server MUST verify that none of the proposed AEAD algorithms in ciphersuites have N_MAX less than 8 bytes. If such an algorithm is detected, server MUST abort the handshake with the 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes one or more AEAD algorithms in the ciphersuites list with N_MAX less than 8 bytes, violating the protocol requirement.",
