        "field": "tls.record",
        "construction_rule": {
            "role": "sender",
            "content": "Once record protection starts in TLS 1.3, the sender MUST protect TLSPlaintext records by applying the record protection mechanisms outlined in the specification and send them as TLSCiphertext."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a protected record, the receiver MUST process TLSCiphertext records as specified, using the appropriate decryption and integrity verification mechanisms. If the record fails verification, the receiver MUST terminate the connection with a fatal error."
        }
    }
}

strategy:
{
    "rule_violation": "The sender fails to apply the required record protection mechanisms when sending TLSPlaintext records, resulting in unprotected or improperly protected records.",
    "testing_strategies": [
