        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record with improper encryption, such as using an incorrect key or cipher suite different from the agreed one.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record missing integrity verification data, i.e., omitting the Message Authentication Code (MAC) entirely.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record with a corrupted or invalid MAC, resulting from intentional modification of the record after encryption.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record with padding that does not conform to the specification’s padding rules, such as padding of an unexpected length or format.",
            "expected_behavior": "Alert"
        }
    ]
}

