rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "sender",
            "content": "The sender may pad encrypted TLS records to increase the TLSCiphertext size, this allows the sender to obscure the actual data size from passive observers."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "The receiver must accept padded TLS records and correctly remove the padding after decryption."
        }
    }
}

strategy:
{
    "rule_violation": "The sender pads TLS records incorrectly, either by exceeding the maximum record size or using improper padding methods.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLS record that has been padded to exceed the maximum allowed record size of 2^14 + 256 bytes.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLS record with non-zero padding that ends with a byte other than the padding length indicator.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLS record that includes invalid padding (e.g., random bytes) not according to any padding scheme.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send a TLS record where the padding length exceeds the actual data length in the record.",
            "expected_behavior": "Alert"
        }
    ]
}

