rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "When no more messages will be sent, the sender MUST send a close_notify alert to notify the recipient of the end of the session."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a close_notify alert, the receiver MUST ignore any data received after this alert and consider it out of scope for the current connection."
        }
    }
}

strategy:
{
    "rule_violation": "The sender violates the construction rule by not sending a close_notify alert to notify the recipient of the end of the session, either omitting it entirely or sending an invalid or malformed close_notify alert.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Terminate a session without sending the close_notify alert and observe the recipient's behavior.",
            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a close_notify alert with an invalid content type value (e.g., a random value like 0xFF instead of 0x14) and observe the response.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a malformed close_notify alert with a corrupted record length field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a close_notify alert as part of a fragmented record and ensure the record is incomplete or improperly assembled.",
            "expected_behavior": "Alert"
        }
    ]
}

