rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "The client using an application protocol over TLS must ensure that any data sent after the closure of the TLS connection is preceded by a 'close_notify' alert, indicating the intent to end the connection."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must handle a 'close_notify' alert by stopping the processing of received data and must not indicate end-of-data to the application layer until a 'close_notify' alert has been received."
        }
    }
}

