    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "When sending a KeyUpdate message with request_update set to 'update_requested', the client must ensure that implementations should expect to receive an arbitrary number of additional messages, as some may be already in flight."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a KeyUpdate with request_update set to 'update_requested', the server must be capable of handling an arbitrary number of messages that may be received between its own KeyUpdate message and the client's KeyUpdate response endorsement."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to handle the construction of a KeyUpdate message properly when `request_update` is set to 'update_requested', either by not sending a KeyUpdate message when expected or failing to manage multiple inflight messages during the transition.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
