        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a KeyUpdate message with `request_update` set to 'update_requested', followed by an excessive number of arbitrary protocol messages (greater than buffer or queue limitations).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a KeyUpdate message with `request_update` set to 'update_requested' but fail to follow up with the required acknowledgment KeyUpdate message from the client.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a malformed KeyUpdate message with `request_update` incorrectly set to an undefined or invalid value (e.g., 0x02).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Do not send a KeyUpdate message with `request_update` set to 'update_requested' even when the update is logically required by the protocol.",
            "expected_behavior": "Timeout"
        }
    ]
}

