rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "client",
            "content": "When using AES-GCM in TLS 1.3 to encrypt data, the client MUST ensure that no more than 2^24.5 full-size records are encrypted on a given connection, maintaining a safety margin of approximately 2^-57 for AE security."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST monitor the number of records encrypted using AES-GCM and ensure it does not exceed 2^24.5 full-size records on a single connection to maintain a safety margin of approximately 2^-57 for AE security. If exceeded, the server SHOULD terminate the connection."
        }
    }
}

