rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When including the Signature Algorithms Extension in ClientHello, the client MUST ensure that for RSASSA-PSS algorithms, the 'salt length' used MUST equal the length of the digest algorithm. If the public key is in an X.509 certificate, RSASSA-PSS OID MUST be used, and parameters MUST be DER encoded."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving and processing the Signature Algorithms Extension, the server MUST verify that for RSASSA-PSS algorithms, the salt length equals the digest algorithm's length. If a public key is in an X.509 certificate, the server MUST ensure it uses the RSASSA-PSS OID with DER encoded parameters. If the public key parameters are present, parameters in the signature MUST match those in the public key."
        }
    }
}

strategy:
{
    "rule_violation": "The client provides invalid RSASSA-PSS configurations in the Signature Algorithms Extension, such as mismatched salt length for the digest algorithm, an invalid RSASSA-PSS OID, or improperly encoded parameters.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension containing an RSASSA-PSS algorithm where the salt length is greater than the digest length (e.g., salt length 64 for SHA-256 with digest length 32).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension containing an RSASSA-PSS algorithm where the salt length is less than the digest length (e.g., salt length 16 for SHA-512 with digest length 64).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension containing an RSASSA-PSS algorithm using a public key in an X.509 certificate without the explicit RSASSA-PSS OID.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension containing an RSASSA-PSS algorithm with incorrectly DER-encoded parameters.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Signature Algorithms Extension",
            "field": "tls.handshake.sig_hash_algs",
            "description": "Send a ClientHello message with the Signature Algorithms Extension containing an RSASSA-PSS signature algorithm where the parameters in the signature do not match those in the public key.",
            "expected_behavior": "Alert"
        }
    ]
}

