rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.sig_hash_algs",
        "construction_rule": {
            "role": "client",
            "content": "When including the Signature Algorithms Extension in ClientHello, the client MUST ensure that for RSASSA-PSS algorithms, the 'salt length' used MUST equal the length of the digest algorithm. If the public key is in an X.509 certificate, RSASSA-PSS OID MUST be used, and parameters MUST be DER encoded."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving and processing the Signature Algorithms Extension, the server MUST verify that for RSASSA-PSS algorithms, the salt length equals the digest algorithm's length. If a public key is in an X.509 certificate, the server MUST ensure it uses the RSASSA-PSS OID with DER encoded parameters. If the public key parameters are present, parameters in the signature MUST match those in the public key."
        }
    }
}

