rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client",
            "content": "When a user decides to cancel a handshake before its completion for reasons unrelated to protocol failures, the client SHOULD send a 'user_canceled' alert with AlertLevel set to warning, followed by a 'close_notify' alert."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a 'user_canceled' alert with AlertLevel set to warning, the server SHOULD prepare to close the connection. If followed by a 'close_notify', the server should gracefully close the connection."
        }
    }
}

strategy:
{
    "rule_violation": "The client provides incorrect alerts during handshake cancellation by not sending a 'user_canceled' alert with AlertLevel set to warning, or by omitting the 'close_notify' alert.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 'user_canceled' alert with AlertLevel set to fatal instead of warning, followed by a 'close_notify' alert.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 'user_canceled' alert with AlertLevel set to warning but do not send a subsequent 'close_notify' alert.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 'close_notify' alert without a preceding 'user_canceled' alert.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 'user_canceled' alert but use an invalid alert description code.",
            "expected_behavior": "Alert"
        }
    ]
}

