rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "client/server",
            "content": "When sending an error alert, the TLS implementation MUST use the 'Alert (21)' content type in the 'tls.record.content_type' field to indicate an error condition to the peer."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "Upon receiving an error alert (indicated by 'Alert (21)' in 'tls.record.content_type'), the TLS implementation MUST terminate the connection, indicate the error to the application, and MUST NOT allow any further data to be sent or received on the connection."
        }
    }
}

