rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "server",
            "content": "The server should send a 'handshake_failure' alert message when it is unable to negotiate an acceptable set of security parameters given the options available in the ClientHello."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receipt of a 'handshake_failure' alert message, the client must understand that the server could not find an acceptable set of security parameters from the provided options and should attempt a different configuration of security options if retrying the connection."
        }
    }
}

