        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.padding",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing records in TLS 1.3, the sender MUST pad all-zero octets to enforce a quick detection of padding errors."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a record, the receiver MUST check for all-zero padding octets. If the padding is not all-zero, it indicates a padding error, and the receiver MUST handle the error appropriately, possibly by terminating the connection."
        }
    }
}

