rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "server",
            "content": "The server must construct the bad_record_mac alert to indicate that a record received could not be deprotected. This alert is intended for use with AEAD algorithms where decryption and verification failures are bundled."
        },
        "processing_rule": {
            "role": "server",
            "content": "If a deprotection failure occurs while processing a record due to AEAD algorithms, the server must return a bad_record_mac alert to the client. This ensures proper signaling of errors while avoiding side-channel attacks."
        }
    }
}

strategy:
{
    "rule_violation": "The server fails to construct or send a bad_record_mac alert when a deprotection failure occurs due to AEAD algorithms, violating the requirement to signal decryption or verification failures.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Simulate the reception of a TLS record that cannot be deprotected due to an AEAD decryption failure, by purposely modifying the encrypted content of an AEAD record.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Send a TLS record with a manipulated tag (authentication tag) that does not match the content, designed to cause a verification failure during deprotection.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record",
            "description": "Introduce random errors into the AEAD-encrypted payload of a TLS record, ensuring the record cannot be deprotected correctly.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "server",
            "content": "The server must construct the bad_record_mac alert to indicate that a record received could not be deprotected. This alert is intended for use with AEAD algorithms where decryption and verification failures are bundled."
        },
        "processing_rule": {
            "role": "server",
            "content": "If a deprotection failure occurs while processing a record due to AEAD algorithms, the server must return a bad_record_mac alert to the client. This ensures proper signaling of errors while avoiding side-channel attacks."
        }
    }
}

