rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.length",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing handshake messages, the sender MUST ensure that every message includes a properly encoded 'tls.handshake.length' field that accurately represents the length of the message content, exclusive of the overall handshake message header."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Peers receiving a handshake message MUST verify that the 'tls.handshake.length' field does not extend beyond the actual message boundary. If a message includes a length extending beyond the message boundary or contains an out-of-range length, the receiver MUST terminate the connection with a 'decode_error' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The sender constructs handshake messages with an improperly encoded 'tls.handshake.length' field, causing it to inaccurately represent the length of the message content.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a handshake message with the 'tls.handshake.length' field set to a value greater than the total message length, causing it to extend beyond the actual content.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a handshake message with the 'tls.handshake.length' field set to a value less than the actual message content, resulting in incomplete data representation.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a handshake message with the 'tls.handshake.length' field set to zero, despite there being content present.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.length",
            "description": "Send a handshake message with a malformed 'tls.handshake.length' field, such as having an incorrect encoding size.",
            "expected_behavior": "Alert"
        }
    ]
}

