rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "sender",
            "content": "If access control is applied during a handshake, and the sender decides not to proceed with negotiation despite a valid certificate or PSK being received, the sender MUST generate a TLS alert message with the alert description 'access_denied'."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving an 'access_denied' alert during a handshake, the receiver MUST terminate the handshake process and treat the session as failed."
        }
    }
}

strategy:
{
    "rule_violation": "The sender fails to generate a 'access_denied' alert message when access control is applied and negotiation is not proceeded despite receiving a valid certificate or PSK.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a TLS 1.3 handshake message without generating an 'access_denied' alert when a valid certificate is received, but access control decides to block the negotiation.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a TLS 1.3 handshake message without generating an 'access_denied' alert when a valid PSK is received, but access control prevents proceeding with the session.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a TLS 1.3 handshake message generating a different alert than 'access_denied' after receiving a valid certificate and the decision is made not to proceed.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Omit sending any alert message entirely after receiving a valid certificate while access control rules mandate 'access_denied'.",
            "expected_behavior": "Alert"
        }
    ]
}

