rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extension.type",
        "construction_rule": {
            "role": "client",
            "content": "Within a ClientHello message, the client MUST NOT include more than one instance of the Supported Groups Extension in a given extension block. The extension block refers to the sequence of extensions in a handshake message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST check that there is no more than one Supported Groups Extension in the extension block. If multiple instances are present, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes multiple instances of the Supported Groups Extension within the extension block of a ClientHello message, violating the requirement to include it only once.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message with two instances of the Supported Groups Extension in the extension block.",
            "expected_behavior": "Alert"
        },
        {
