            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message with duplicate Supported Groups Extensions, each containing different group values.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message with the Supported Groups Extension appearing non-contiguously within the extension block (interleaved with other extensions).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Supported Groups Extension",
            "field": "tls.handshake.extension.type",
            "description": "Send a ClientHello message where all extensions in the extension block are duplicated, including the Supported Groups Extension.",
            "expected_behavior": "Alert"
        }
    ]
}

