rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client",
            "content": "When sending a Key Share Extension, the client MUST include a public value Q for curves secp256r1, secp384r1, and secp521r1. Q must be a valid point on the elliptic curve, not the point at infinity (O), with x and y integers in the correct interval, and (x,y) must satisfy the elliptic curve equation."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a Key Share Extension, the server MUST validate the client's public value Q for curves secp256r1, secp384r1, and secp521r1, ensuring it is not the point at infinity (O), that x and y are integers in the correct interval, and that (x, y) satisfies the elliptic curve equation."
        }
    }
}

strategy:
{
