            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a Key Share Extension with malformed coordinates that include non-integer values for curve secp256r1.",
            "expected_behavior": "Alert"
        }
    ]
}

