    "rule_violation": "The sender fails to send a 'close_notify' alert using tls.record.content_type before closing its write side of the connection, violating the requirement to properly terminate the connection.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Close the write side of the connection without sending a 'close_notify' alert.",
            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 'close_notify' alert and immediately close the connection without waiting for the receiver's acknowledgement.",
            "expected_behavior": "Timeout"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an incorrect alert type instead of 'close_notify' before closing the write side of the connection.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a 'close_notify' alert with altered content type values in the record layer.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "Before closing its write side of the connection, each party MUST send a 'close_notify' alert using the tls.record.content_type unless an error alert has already been sent."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a 'close_notify' alert using tls.record.content_type, the receiver should acknowledge and begin shutdown of its own connection layer sending side."
        }
    }
}

