rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "Extension: key_share",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message, the client MUST ensure that there is no more than one Key Share Extension present in a given extension block."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST verify that there is not more than one Key Share Extension in the extension block. If multiple Key Share Extensions are found, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes more than one Key Share Extension in a single ClientHello extension block, violating the requirement for having only one Key Share Extension.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ClientHello message containing two identical Key Share Extensions within the same extension block.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ClientHello message with two different Key Share Extensions in a single extension block, each offering different key shares.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ClientHello message with multiple Key Share Extensions, each containing overlapping key shares.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "Extension: key_share",
            "description": "Send a ClientHello message where one Key Share Extension is immediately followed by another within the extension block.",
            "expected_behavior": "Alert"
        }
    ]
}

