rule:
{
  "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
          "role": "sender",
          "content": "The sender must ensure that the content type is accurately appended at the end of the TLSCiphertext.encrypted_record for successful decryption."
        },
        "processing_rule": {
          "role": "receiver",
          "content": "Upon successful decryption of TLSCiphertext.encrypted_record, the receiver must scan the field from the end toward the beginning to locate the first non-zero octet, which represents the content type of the message."
        }
    }
}

strategy:
{
    "rule_violation": "The sender fails to append the content type accurately at the end of the TLSCiphertext.encrypted_record, leading to incorrect or missing content type information.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext message where the content type is missing entirely from the end of the TLSCiphertext.encrypted_record.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext message where the content type is set to an invalid value (e.g., 0xFF) at the end of the TLSCiphertext.encrypted_record.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext message where the content type is appended at an incorrect position in the middle of the TLSCiphertext.encrypted_record instead of at the end.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext message with multiple content type values appended at the end of the TLSCiphertext.encrypted_record (e.g., 0x14 followed by 0x17).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext message with the correct content type appended but followed by an extra erroneous octet (e.g., 0x14 followed by 0xFF).",
            "expected_behavior": "Alert"
        }
    ]
}

