rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "server",
            "content": "When performing handshake cryptographic operations, such as verifying a signature, validating a Finished message, or a PSK binder, the server MUST ensure that the processes are executed correctly without failure."
        },
        "processing_rule": {
            "role": "server",
            "content": "If a handshake cryptographic operation fails (e.g., incorrect signature verification, unable to validate a Finished message, or a PSK binder), the server MUST send a decrypt_error alert and terminate the handshake."
        }
    }
}

strategy:
{
    "rule_violation": "The server fails to correctly execute handshake cryptographic operations, resulting in improper verification of the signature, incorrect validation of the Finished message, or failure in PSK binder processes.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Simulate an incorrect signature verification during the handshake by modifying the signature data in the server's certificate.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a Finished message with incorrect key material, ensuring the server is unable to validate the message.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Use an invalid PSK binder value to simulate a failed validation process during the resumption handshake attempt.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Alter the message hash used in handshake messages to simulate a cryptographic failure in the handshake process.",
            "expected_behavior": "Alert"
        }
    ]
}

