        "construction_rule": {
            "role": "client",
            "content": "When using ChaCha20/Poly1305 cipher, the client should ensure the record sequence number is monitored to avoid wrapping before reaching the safety limit."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must track the record sequence number for ChaCha20/Poly1305 cipher to determine if it wraps before reaching the safety limit and should abort the session if safety limits are at risk."
        }
    }
}

