rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "sender",
            "content": "When sending a TLSCiphertext record, the sender MUST ensure that the record length does not exceed 2^14 + 256 bytes."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a TLSCiphertext record, the receiver MUST check that the record length is not greater than 2^14 + 256 bytes. If the record length exceeds this, or if the decrypted TLSPlaintext record exceeds 2^14 bytes (or another negotiated limit), the record is considered corrupted. Such a situation should trigger an alert and the connection should be aborted unless messages were corrupted in the network."
        }
    }
}

