rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Ec Point Formats Extension",
        "field": "Extension: ec_point_formats",
        "construction_rule": {
            "role": "client",
            "content": "In TLS 1.3, the client MUST include the 'Ec Point Formats Extension' in the ClientHello message to specify its supported EC point formats for elliptic curve cryptography."
        },
        "processing_rule": {
            "role": "server",
            "content": "In TLS 1.3, the server MUST include its response for the 'Ec Point Formats Extension' in one of the following messages: ServerHello, EncryptedExtensions, HelloRetryRequest, or Certificate, as determined by the context of the handshake. The response MUST properly represent the server's supported EC point formats. If the client or server encounters an invalid or mismatched extension, they MUST abort the handshake with a 'handshake_failure' alert."
        }
    }
}

