        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "The sender must ensure that all alerts listed in Section 6.2 are sent with AlertLevel=fatal in TLS 1.3. Unknown Alert types must also be constructed as error alerts."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving an alert, the receiver must treat it as an error alert regardless of the AlertLevel specified in the message, including unknown Alert types."
        }
    }
}

strategy:
{
  "rule_violation": "The sender sends alerts with an AlertLevel other than fatal in TLS 1.3, including unknown Alert types, violating the requirement to use fatal AlertLevel for certain alerts.",
  "testing_strategies": [
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.record.content_type",
      "description": "Send an alert message with AlertLevel set to warning instead of fatal for a known alert type such as 'close_notify'.",
      "expected_behavior": "Alert"
    },
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.record.content_type",
      "description": "Send an alert message with AlertLevel set to warning instead of fatal for an unknown alert type (e.g., 0xFF).",
      "expected_behavior": "Alert"
    },
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.record.content_type",
      "description": "Send an alert message with AlertLevel not set (omitted) for a known alert type such as 'unexpected_message'.",
      "expected_behavior": "Alert"
    },
    {
      "protocol": "TLS 1.3",
      "message": "No Extension",
      "field": "tls.record.content_type",
      "description": "Send an alert message with an invalid AlertLevel value (e.g., 0x03) for a known alert type such as 'bad_record_mac'.",
      "expected_behavior": "Alert"
    }
  ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.length",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing Application Data records in TLS 1.3, the sender MAY include a zero-length TLSInnerPlaintext.content field to allow generation of plausibly-sized cover traffic in contexts where avoiding the correlation of activity may be important."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving an Application Data record, the receiver MUST properly handle zero-length TLSInnerPlaintext.content. This ensures the record is valid and maintains the intended context-sensitive privacy functionality."
        }
    }
}

strategy:
{
    "rule_violation": "The sender improperly constructs the Application Data record by violating the handling of the TLSInnerPlaintext.content field, either by including invalid lengths or missing fields.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send an Application Data record with a negative value in the TLSInnerPlaintext.content field length (not permitted in protocol logic).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send an Application Data record with the TLSInnerPlaintext.content field explicitly set to a random string not adhering to encoding rules.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send an Application Data record with the TLSInnerPlaintext.content field length set to zero, but with extra trailing unexpected padding bytes.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.length",
            "description": "Send an Application Data record missing the TLSInnerPlaintext.content field entirely.",
            "expected_behavior": "Alert"
        }
    ]
}

