rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client",
            "content": "In the ClientHello message, the client MUST include a 'Key Share Extension' with requests specifying supported key exchange groups and corresponding public key shares in the 'tls.handshake.extensions_key_share_key_exchange' field."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello message with a 'Key Share Extension', the server MUST process the 'tls.handshake.extensions_key_share_key_exchange' field in accordance with the specified key exchange protocol, and respond with a 'Key Share Extension' in the ServerHello, EncryptedExtensions, HelloRetryRequest, or Certificate messages."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to include a proper 'Key Share Extension' in the ClientHello message, either by omitting it entirely or including unsupported key exchange groups or malformed public key shares.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message without the 'Key Share Extension'.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with the 'Key Share Extension' specifying unsupported key exchange groups.",
            "expected_behavior": "HelloRetryRequest"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with the 'Key Share Extension' containing an incorrectly formatted public key share.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with an empty 'Key Share Extension' (zero length).",
            "expected_behavior": "Alert"
        }
    ]
}

