rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "When generating a TLSCiphertext record, the sender MAY choose to add padding. Padding must consist of a string of zero-valued bytes that are appended to the tls.record.content_type field before encryption."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a TLSCiphertext record, the receiver MUST correctly handle zero-valued padding bytes appended to the tls.record.content_type field during decryption. These padding bytes must be ignored during message processing."
        }
    }
}

strategy:
{
    "rule_violation": "The sender violates the padding rule by either omitting padding entirely when it is required, using non-zero-valued bytes for padding, or using an excessive amount of padding that exceeds reasonable limits.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext record without any padding bytes appended to the tls.record.content_type field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext record with padding bytes consisting of non-zero values (e.g., 0x01) appended to the tls.record.content_type field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext record with an excessive amount of padding (e.g., 1024 zero-valued bytes) appended to the tls.record.content_type field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext record with malformed padding (e.g., a sequence of non-zero and zero bytes mixed together) appended to the tls.record.content_type field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send a TLSCiphertext record with padding bytes properly appended, but include an incorrect tls.record.content_type value (e.g., a reserved value).",
            "expected_behavior": "Alert"
        }
    ]
}

