rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "Prior to closing a TLS connection, the sender must send a 'close_notify' alert to indicate that no more data will be sent. This requires setting 'tls.record.content_type' to a specific value indicating 'close_notify'."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "If a transport-level close is received before the 'close_notify' alert with 'tls.record.content_type' indicating such, the receiver does not have assurance that all the data from the sender has been received and must treat the connection closure as potentially incomplete."
        }
    }
}

