rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Psk Key Exchange Modes Extension",
        "field": "Extension: psk_key_exchange_modes",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST ensure that no more than one Psk Key Exchange Modes Extension is included in a given extension block when constructing the ClientHello message."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST verify that there is not more than one Psk Key Exchange Modes Extension in the extension block. If more than one instance is found, the server MUST terminate the handshake with an 'illegal_parameter' alert."
