rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Groups Extension",
        "field": "tls.handshake.extensions_supported_groups",
        "construction_rule": {
            "role": "client",
            "content": "The client must include its 'Supported Groups Extension' requests in the ClientHello message by populating the tls.handshake.extensions_supported_groups field with the supported groups it prefers."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must respond to the client's 'Supported Groups Extension' requests by including the extension in one or more of the following messages: ServerHello, EncryptedExtensions, HelloRetryRequest, or Certificate. The corresponding tls.handshake.extensions_supported_groups field in these messages must contain the group's response that matches the server's configuration."
        }
    }
}

