rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "The client must include cipher suites in tls.handshake.ciphersuites that match the server's security requirements during ClientHello in a TLS 1.3 handshake."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the server determines that the cipher suites in tls.handshake.ciphersuites do not meet its security requirements, the server must return an insufficient_security alert instead of 'handshake_failure' to indicate that the negotiation failed due to the client's lack of support for secure parameters."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes cipher suites in tls.handshake.ciphersuites that are not compatible with the server's security requirements, violating the construction rule.",
    "testing_strategies": [
