        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with a single, obsolete cipher suite such as TLS_RSA_WITH_DES_CBC_SHA.",
