rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Server Name Extension",
        "field": "tls.handshake.extensions_server_name",
        "construction_rule": {
            "role": "server",
            "content": "When constructing a ServerHello message in response to a ClientHello containing a 'server_name' extension, if no matching server is identified by the server_name provided by the client, the server must include the appropriate error alert indicating that no server exists with the given name."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a ServerHello message with the appropriate alert indicating no server exists for the 'server_name' requested, the client must terminate the handshake session and alert the user that no such named server is available."
        }
    }
}

