rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "For each potential Pre Shared Key Extension in the ClientHello message, the client must compute an Early Secret corresponding to the identity in 'tls.handshake.extensions.psk.identity.identity'. If no Pre Shared Key Extension is selected by the server, the client must compute an Early Secret corresponding to a zero Pre-Shared Key (PSK)."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must verify the Early Secret computed by the client for the selected Pre Shared Key Extension or, if no PSK is selected, validate the Early Secret corresponding to the zero PSK. If validation fails, the server must abort the handshake with a 'decrypt_error' alert."
        }
    }
}

