rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "In TLS 1.3, when sending a ClientHello with pre_shared_key extension, clients MUST use the label 'ext binder' for binder_key computation if the PSK is externally provisioned and 'res binder' if it is provisioned for session resumption."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a pre_shared_key extension, server MUST validate that the label used for binder_key calculation is 'ext binder' for external PSKs and 'res binder' for resumption PSKs. If labels do not match, the server MUST reject the PSK with an 'illegal_parameter' alert."
        }
    }
}

