rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Signature Algorithms Extension",
        "field": "tls.handshake.extension.type",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message in TLS 1.3, the client MUST include at most one Signature Algorithms Extension in a given extension block. The extension block must not contain multiple entries of the Signature Algorithms Extension."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST verify that there is no more than one Signature Algorithms Extension in the extension block. If multiple Signature Algorithms Extensions are present, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

