rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "When a PSK key establishment is desired, the client must include a PSK identity in the Pre Shared Key Extension."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a Pre Shared Key Extension, if the PSK identity is not acceptable or not provided, the server may optionally send an 'unknown_psk_identity' alert. Alternatively, the server may send a 'decrypt_error' alert to indicate that the provided PSK identity is invalid."
        }
    }
}

strategy:
