        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "Extension: pre_shared_key",
        "construction_rule": {
            "role": "client",
            "content": "When sending the ClientHello message in TLS 1.3, the client MUST include its 'Pre Shared Key Extension' within the Extension: pre_shared_key field for the server to process pre-shared key offers."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello message, the server MUST located the 'Pre Shared Key Extension' within the Extension: pre_shared_key field in order to correctly process and respond to the pre-shared key offers as part of the ServerHello, EncryptedExtensions, HelloRetryRequest, or Certificate messages."
        }
    }
}

