        "message": "No Extension",
        "field": "tls.record",
        "construction_rule": {
            "role": "client",
            "content": "When generating a TLSCiphertext record, the client MUST set the padding octets to all zeros before encrypting the record"
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving and decrypting a TLSCiphertext record, the server MUST ensure that any padding octets are processed correctly, though it does not need to verify the padding when decrypting."
        }
    }
}

