rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client/server",
            "content": "When constructing a handshake message in TLS 1.3 that does not allow extensions, client or server MUST ensure the absence of any extensions in the message to comply with protocol restrictions."
        },
        "processing_rule": {
            "role": "client/server",
            "content": "Upon receiving a handshake message, if the message contains an extension that is prohibited for inclusion, the endpoint (client or server) MUST send an 'unsupported_extension' alert and abort the handshake."
        }
    }
}

