    "rule_violation": "The client sends data not considered safe for replay when using early data in TLS 1.3, despite the unknown level of replay protection by the server.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send early data in a TLS 1.3 connection including sensitive user credentials, which are not safe for replay.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send early data consisting of non-idempotent operations in a TLS 1.3 connection.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send early data that includes state-changing commands in a TLS 1.3 connection.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send early data containing financial transaction requests in a TLS 1.3 connection.",
            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When using early data in TLS 1.3, the client MUST only send data considered safe for replay as the level of replay protection by the server is unknown."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server should consider the early data potentially replayed due to client's inability to determine server's replay protection mechanism."
        }
    }
}

