rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "server",
            "content": "When responding to an invalid connection retry attempt from a client (as outlined in [RFC7507]), the server must construct an alert message with tls.record.content_type set to 'alert' and include the inappropriate_fallback alert."
        },
        "processing_rule": {
            "role": "client",
            "content": "Upon receiving a message where tls.record.content_type is 'alert' and the alert type is inappropriate_fallback, the client must terminate the connection and log or handle the invalid connection retry attempt as specified."
        }
    }
}

strategy:
{
    "rule_violation": "The server constructs an alert message in response to an invalid connection retry attempt but fails to set the tls.record.content_type to 'alert' or does not include the inappropriate_fallback alert.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an alert message with tls.record.content_type set to an incorrect value, such as 'handshake', instead of 'alert'.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an alert message with the correct tls.record.content_type as 'alert' but omit the inappropriate_fallback alert code.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an alert message with tls.record.content_type set to 'alert' and include a wrong alert type, such as 'close_notify', instead of inappropriate_fallback.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.record.content_type",
            "description": "Send an alert message by excluding the tls.record.content_type field entirely.",
            "expected_behavior": "Alert"
        }
    ]
}

