rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "If a given secret is not available and 'PSK' is not being used, the client must use the 0-value consisting of a string of Hash.length bytes set to zeros in the Early Secret, specifically executing HKDF-Extract(0, 0) without skipping any rounds."
        },
        "processing_rule": {
            "role": "server",
            "content": "If a given secret is missing, the server must ensure the use of a 0-value string of Hash.length bytes set to zeros in computations, without skipping protocol rounds, as Early Secret should still perform HKDF-Extract(0, 0) even when PSK is not used."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to use the 0-value consisting of a string of Hash.length bytes set to zeros in the Early Secret when the PSK is not being used and executes computations incorrectly, violating the required HKDF-Extract(0, 0) process.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message where the Early Secret is derived using a random non-zero value instead of the required 0-value string of Hash.length bytes set to zeros.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message where the Early Secret computation skips the HKDF-Extract(0, 0) step.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message where the Early Secret is derived using a partially zero-filled string instead of a full Hash.length string of zeros.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message where the Early Secret computation uses an incorrect hash algorithm, deviating from the standard HKDF-Extract(0, 0) process.",
            "expected_behavior": "Alert"
        }
    ]
}

