rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "client",
            "content": "The client must compute the ECDH shared secret by applying the scalar multiplication function using its secret key as the scalar input and the peer's public key as the u-coordinate point input. The resulting shared secret must be used raw without further processing."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must verify that the ECDH shared secret received during the handshake complies with the requirement: it must be generated by applying the scalar multiplication function using the appropriate secret key and peer's public key. Any failure in this verification must result in the termination of the handshake with a handshake_failure alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to compute the ECDH shared secret correctly, either by not applying the scalar multiplication function properly, using an incorrect secret key, using an invalid peer public key, or applying additional processing to the shared secret instead of using it raw.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ClientHello message with an ECDH shared secret computed using an incorrect secret key, leading to an invalid shared secret.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ClientHello message with an ECDH shared secret computed using an invalid peer public key that does not conform to the required curve.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ClientHello message with an ECDH shared secret that has been processed further (e.g., hashed or altered) instead of using it raw.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.random",
            "description": "Send a ClientHello message with an incorrectly formatted ECDH shared secret (e.g., containing invalid data or padding).",
            "expected_behavior": "Alert"
        },
        {
