rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "When constructing ClientHello in TLS 1.3 with pre_shared_key extension, the client must compute each entry in the binders list as an HMAC over a transcript hash containing a partial ClientHello up to and including the PreSharedKeyExtension.identities field. The length fields for the message, including the length of the extensions block and pre_shared_key extension, must be set as if the binders of correct lengths were present."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving ClientHello with pre_shared_key extension, the server must verify each binder value in the binders list by recomputing the HMAC over the received partial ClientHello transcript hash including up to PreSharedKeyExtension.identities field. If the computed binder does not match the received binder, the server must abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

