        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When constructing and sending ClientHello messages, the client MUST be aware that messages might encounter delays due to retransmissions and TCP buffering. Clients should account for such possible delays to accommodate timing windows of at least ten seconds to address clock errors and variations in measurement."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello message, the server MUST consider possible transmission delays (e.g., due to retransmissions and TCP buffering). Servers should allow timing windows on the order of ten seconds to accommodate variations in client clock accuracy and measurement."
        }
    }
}

