            "content": "For optimal anti-replay protection in distributed systems with high rates of resumption and 0-RTT, the server must ensure that a session ticket is associated with a single authoritative storage zone."
        },
        "processing_rule": {
            "role": "server",
            "content": "If a session ticket is presented for 0-RTT, the server must refuse 0-RTT resumption for that ticket if it is not in the authoritative storage zone, and proceed with a full handshake instead."
        }
    }
}

