            "expected_behavior": "Alert"
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message in the absence of any context, the client MUST set the context_value to zero length, ensuring that providing no context computes the same value as providing an empty context."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello message with no context provided, the server MUST interpret the context_value as zero length. Providing no context should result in the same computed value as providing an empty context."
        }
    }
}

