rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "client or server",
            "content": "When constructing a ClientHello, ServerHello, or HelloRetryRequest message, the implementation MUST include and use the supported_versions extension to indicate applicable supported protocol versions."
        },
        "processing_rule": {
            "role": "peer (client or server)",
            "content": "Upon receiving a ClientHello, ServerHello, or HelloRetryRequest message, the peer MUST validate that the supported_versions extension is present. If the extension is not included, the message is considered non-compliant and the peer MUST abort the handshake."
        }
    }
}

