rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Pre Shared Key (PSK) Extension, the client must ensure that each PSK identity within the 'tls.handshake.extensions.psk.identity.identity' field is generated to reference either a self-contained ticket or a database key. If the latter, the client should anticipate that the corresponding PSKs will be deleted after use to ensure forward secrecy."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Pre Shared Key (PSK) Extension, the server must process 'tls.handshake.extensions.psk.identity.identity' to verify whether each identity refers to a securely managed key. If the PSKs are database keys and are properly deleted upon use, the server must treat these connections as providing forward secrecy."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to properly construct the Pre Shared Key (PSK) Extension by either not generating a self-contained ticket or using a database key without ensuring that the PSK is deleted after use for forward secrecy.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with a PSK identity that is indeed a database key but without any mechanism or indication for the server to ensure that the key is deleted after a successful handshake.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with an invalid PSK identity format that does not properly reference either a self-contained ticket or a database key.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.identity.identity",
            "description": "Send a ClientHello message with PSK identities that mix valid self-contained tickets with malformed database keys.",
            "expected_behavior": "Alert"
        }
    ]
}

