rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.type",
        "construction_rule": {
            "role": "standards body",
            "content": "When allocating new values for tls.handshake.type in the TLS HandshakeType registry, they MUST be allocated via a Standards Action according to [RFC8126]."
        },
        "processing_rule": {
            "role": "implementer",
            "content": "Implementers must ensure that only standard-approved values of tls.handshake.type, allocated via Standards Action as per [RFC8126], are recognized and processed to maintain compliance with future protocol extensions."
        }
    }
}

