rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client and server",
            "content": "Both client and server implementations are RECOMMENDED to provide a separate interface for the early exporter in the handshake process to ensure that the exporter user does not accidentally use an early exporter when a regular exporter is intended, or vice versa."
        },
        "processing_rule": {
            "role": "client and server",
            "content": "Both client and server must ensure that during the handshake process, the interface for the early exporter is clearly separated from the regular exporter interface. This helps prevent operational mistakes and ensures compliance with the recommendation."
        }
    }
}

