rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.session_id",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello for 0-RTT, ensure storage for each zone is separate, allowing only one replay per zone through proper management of the tls.handshake.session_id, enhancing security against replay attacks."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server must verify that only one 0-RTT replay occurs per zone by checking that each session referenced by tls.handshake.session_id is used once per zone. If the replay is detected in the same zone, the handshake must be aborted."
        }
    }
}

