    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the ClientHello message, the client MUST populate the 'tls.handshake.random' field with a value generated using a secure random number generator to ensure uniqueness and prevent replay attacks."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST ensure the prevention of replayed ClientHello messages by locally recording data from recently received ClientHellos, such as the 'tls.handshake.random' field, and rejecting repeats. Alternatively, the server MAY use another method to ensure replay protection."
        }
    }
}

