rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.identity.identity",
        "construction_rule": {
            "role": "client",
            "content": "The client must use the pre_shared_key extension to send PSK identities derived from the resumption_master_secret value of a prior connection or from a pre-established externally shared key. These identities must be properly encoded in the 'tls.handshake.extensions.psk.identity.identity' field."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server must process the pre_shared_key extension by using the PSK identity from the 'tls.handshake.extensions.psk.identity.identity' field as one of the two input secrets for deriving keys with the HKDF-Extract and Derive-Secret functions. If the PSK identity is invalid or not recognized, the server must terminate the handshake with a handshake_failure alert."
        }
    }
}

