rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When sending a ClientHello, the client does not need to include any specific timing information but must be prepared for the server to evaluate the appropriateness of initiating 0-RTT based on its timing calculations."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server must compute the expected_arrival_time. If the computed time is outside the acceptable window for 0-RTT data replay protection, the server must reject the 0-RTT data and proceed with a 1-RTT handshake instead."
        }
    }
}

