rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Key Share Extension in TLS 1.3, the client must encode the key_exchange field using the FE2OSP (Field Element to Octet String Conversion Primitive), ensuring that the output octet string ('Z' in IEEE 1363 terminology) has a constant length for the given field. Leading zeros in this octet string MUST NOT be truncated."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Key Share Extension, the server must verify that the key_exchange field has a constant length as per the specified FE2OSP primitive and that no leading zeros in the octet string have been truncated. If these conditions are violated, the server must reject the extension and abort the handshake with a 'decode_error' alert."
        }
    }
}

