    "rule_violation": "The client improperly encodes the key_exchange field in the Key Share Extension, either by failing to use the FE2OSP primitive, producing an octet string that is not of constant length, or by truncating leading zeros from the octet string.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with the Key Share Extension where the key_exchange field is encoded as a variable-length octet string instead of a constant-length format.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with the Key Share Extension where the key_exchange field is encoded with leading zeros truncated from the octet string.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with the Key Share Extension where the key_exchange field is encoded in an incorrect format, such as an empty octet string (zero-length).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Key Share Extension",
            "field": "tls.handshake.extensions_key_share_key_exchange",
            "description": "Send a ClientHello message with the Key Share Extension where the key_exchange field contains an octet string that is too short or too long, violating the specified constant length.",
            "expected_behavior": "Alert"
        }
    ]
}

action_sequence:
{
    "action_sequence": [
        {
            "action": "update",
            "fields": [
                "tls",
                "tls.record",
                "tls.handshake",
                "Extension: key_share",
                "Key Share extension",
                "Key Share Entry: Group: Reserved",
                "tls.handshake.extensions_key_share_key_exchange"
            ],
            "new_value": [0x01, 0x02]
        }
    ]
}

rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.extensions_length",
        "construction_rule": {
            "role": "client",
            "content": "When sending ClientHello in TLS 1.3, the client MUST include necessary extensions in the message to conform to protocol requirements."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server MUST check for the presence of required extensions. If the ClientHello does not conform by having required extensions, the server MUST abort the handshake with a 'missing_extension' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to include the necessary extensions in the ClientHello message, violating the protocol requirements for TLS 1.3.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message without any extensions.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message missing the 'supported_versions' and 'key_share' extensions.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with the extensions length set to zero.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.extensions_length",
            "description": "Send a ClientHello message with an incorrect extension type and missing 'supported_versions' extension.",
            "expected_behavior": "Alert"
        }
    ]
}

