rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "When sending ClientHello, the client must include sufficient and valid information to allow the server to match the expected_arrival_time into a processing window if PSK (Pre-Shared Key) or 0-RTT modes are being considered."
        },
        "processing_rule": {
            "role": "server",
            "content": "If the expected_arrival_time falls within the defined window and a matching ClientHello is found, the server must either abort the handshake with an 'illegal_parameter' alert or accept the PSK while rejecting 0-RTT, ensuring secure protocol compliance."
        }
    }
}

strategy:
{
    "rule_violation": "The client sends a ClientHello message without including sufficient or valid information necessary for the server to match the expected_arrival_time into a processing window when using PSK or 0-RTT modes.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message missing critical timing information required for PSK or 0-RTT to allow expected_arrival_time matching.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message with incorrect timing information, such as a timestamp far in the future or past, disrupting expected_arrival_time processing.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message with a missing or malformed field that the server expects for calculating expected_arrival_time for PSK or 0-RTT.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake",
            "description": "Send a ClientHello message with valid timing information but containing an incompatible PSK identity that leads to processing failures.",
            "expected_behavior": "Alert"
        }
    ]
}

