rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "When constructing a ClientHello message that uses the Pre-Shared Key (PSK) extension, the client MUST include a valid PSK binder in the tls.handshake.extensions.psk.binders field. The PSK binder must be computed as described in Section 4.2.11 of the TLS 1.3 specification."
        },
        "processing_rule": {
            "role": "server",
            "content": "When a ClientHello with the Pre-Shared Key (PSK) extension is received, the server MUST verify the validity of the PSK binder in the tls.handshake.extensions.psk.binders field. The PSK binder must be validated as described in Section 4.2.11. If the PSK binder is invalid or verification fails, the server MUST abort the handshake with a 'decrypt_error' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client fails to include a valid PSK binder in the tls.handshake.extensions.psk.binders field of the ClientHello message, violating the requirement for proper PSK binder computation.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.binders",
