            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.binders",
            "description": "Send a ClientHello message with an empty PSK binder field (zero length).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.binders",
            "description": "Send a ClientHello message with no PSK binder field included at all.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.binders",
            "description": "Send a ClientHello message with the PSK binder calculated using an incorrect hash algorithm.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "Pre Shared Key Extension",
            "field": "tls.handshake.extensions.psk.binders",
            "description": "Send a ClientHello message with a malformed PSK binder field (e.g., incorrect length value).",
            "expected_behavior": "Alert"
        }
    ]
}

