        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server must check if its expected_arrival_time falls within the defined window. If it does, and no matching ClientHello is already found, the server must accept the 0-RTT connection and store the ClientHello for as long as its expected_arrival_time remains inside the window."
        }
    }
}

