rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.random",
        "construction_rule": {
            "role": "client",
            "content": "The client MUST include the 'tls.handshake.random' field in the ClientHello message. This field is used to assist in time validation for 0-RTT and 1-RTT handshakes."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server MUST extract the 'tls.handshake.random' value and use it to calculate the expected arrival time. The server MUST compare the expected arrival time against its wall clock time. If the difference exceeds a configured tolerance (e.g., server-defined threshold), the server MUST reject 0-RTT but MAY proceed with the 1-RTT handshake."
        }
    }
}

