        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving any alert X, the server must verify the alert is sent correctly according to the handshake rules for termination or aborting, and handle it by optionally closing the connection or continuing based on the alert type."
        }
    }
}

