rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "The ClientHello message MUST be properly constructed, ensuring all sections (e.g., version, random, session ID, cipher suites, compression methods, and extensions) adhere to protocol requirements to guarantee validity."
        },
        "processing_rule": {
            "role": "server",
            "content": "The server MUST derive the storage key exclusively from validated sections of the ClientHello, ensuring the integrity and correctness of the parsed fields. If any section is invalid or malformed, the server MUST reject the ClientHello and terminate the handshake with an appropriate alert."
        }
    }
}

