        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client",
            "content": "For X25519 and X448, the client MUST compute the public key to put into the 'KeyShareEntry.key_exchange' structure by applying the ECDH scalar multiplication function to the private scalar of appropriate length and the standard public basepoint. The result SHOULD be placed as the u-coordinate value in 'tls.handshake.extensions_key_share_key_exchange'."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Key Share Extension, the server MUST verify that the 'KeyShareEntry.key_exchange' field contains a valid public key derived by applying the ECDH scalar multiplication function to the corresponding private scalar and basepoint. If the value is invalid or not properly formatted, the server MUST abort the handshake with an 'illegal_parameter' alert."
        }
    }
}

