rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Pre Shared Key Extension, the client MUST ensure that the validated PSK binder or the ClientHello.random is used as the storage key for cryptographic computations, ensuring mitigation against the described attack."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Pre Shared Key Extension, the server MUST validate that the PSK binder or the ClientHello.random is used as the storage key for cryptographic computations. If neither is used, the server MUST abort the handshake with an appropriate alert."
        }
    }
}

strategy:
