rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake",
        "construction_rule": {
            "role": "client",
            "content": "The client must ensure that all parameters in the ClientHello message are included as per the specification, without expecting middleboxes to alter them."
        },
        "processing_rule": {
            "role": "middlebox",
            "content": "A middlebox that forwards ClientHello parameters it does not understand must not process any messages beyond that ClientHello. It must forward all subsequent traffic unmodified, to avoid interoperability failures with newer clients and servers."
        }
    }
}

