rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Key Share Extension",
        "field": "tls.handshake.extensions_key_share_key_exchange",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the Key Share extension for curve P-384, the client must ensure that both the X and Y values are represented by 48 octets each in 'tls.handshake.extensions_key_share_key_exchange'."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a Key Share extension, for curve P-384, the server must verify that the X and Y values in 'tls.handshake.extensions_key_share_key_exchange' are 48 octets each. If not, the server must reject the handshake with an 'illegal_parameter' alert."
        }
    }
}

strategy:
{
    "rule_violation": "The client constructs the Key Share extension for curve P-384 with X and Y values that do not adhere to the required 48-octet length, violating the construction rule.",
