rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Psk Key Exchange Modes Extension",
        "field": "tls.extension.psk_ke_mode",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the PskKeyExchangeModes extension, the client MUST NOT include the reserved values 254 and 255 in the 'tls.extension.psk_ke_mode' field, as they are intended for Private Use."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the PskKeyExchangeModes extension, the server MUST check that the 'tls.extension.psk_ke_mode' does not contain the reserved values 254 or 255. If these values are present, the server SHOULD abort the handshake with an 'illegal_parameter' alert, considering the reserved values for Private Use."
        }
    }
}

