rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.record.content_type",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing an alert message in TLS 1.3, the sender MUST use the 'tls.record.content_type' field to indicate an alert message type, and the alert MUST be declared as fatal if it corresponds to the alerts outlined in the specification or if it is an unknown alert."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving an alert in TLS 1.3, the receiver MUST treat all alerts defined in the relevant section of the TLS 1.3 specification and all unknown alerts as fatal. If such an alert is received, the connection MUST be immediately terminated, and no further data can be processed."
        }
    }
}

