rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Server Name Extension",
        "field": "Extension: server_name",
        "construction_rule": {
            "role": "client",
            "content": "Clients supporting SNI (Server Name Indication) MUST include the server_name extension in ClientHello when connecting to a server that can use this information."
        },
        "processing_rule": {
            "role": "server",
            "content": "Servers MUST be capable of processing the server_name extension if included in ClientHello and adapt operations based on the server_name when furnished by applications capable of using it."
        }
    }
}

