rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extension.type",
        "construction_rule": {
            "role": "client",
            "content": "When including the pre_shared_key extension in ClientHello, the client MUST set the extension type to the value defined by IANA for the 'pre_shared_key' extension, ensuring it matches the registered value."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello with a pre_shared_key extension, the server MUST verify that the extension type corresponds to the registered value defined by IANA. If it does not match, the server SHOULD respond with an 'unsupported_extension' alert."
        }
    }
}

