rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Pre Shared Key Extension",
        "field": "tls.handshake.extensions.psk.binders",
        "construction_rule": {
            "role": "client",
            "content": "When sending ClientHello with multiple PSK identities, the client must correctly compute and include a valid binder value for each PSK identity in tls.handshake.extensions.psk.binders."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello with multiple PSK identities, the server must verify the binder value for each offered identity in tls.handshake.extensions.psk.binders. If any binder is incorrect, the server must reject the ClientHello as specified in Section 4.2.11."
        }
    }
}

strategy:
{
