rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Supported Versions Extension",
        "field": "tls.handshake.extensions.supported_version",
        "construction_rule": {
            "role": "client",
            "content": "When sending a ClientHello in TLS 1.3, the client MUST include a 'supported_versions' extension with 0x0304 (TLS 1.3 version) in its body to indicate an attempt to negotiate using TLS 1.3."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello, the server MUST check the 'supported_versions' extension in the ClientHello for 0x0304. If 0x0304 is included, the client MUST be considered as attempting to negotiate using this specification. If 0x0304 is absent, the server MUST treat the negotiation as aimed at previous versions or abort the handshake depending on its configuration."
        }
    }
}

