rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Psk Key Exchange Modes Extension",
        "field": "tls.extension.psk_ke_mode",
        "construction_rule": {
            "role": "client",
            "content": "When including PskKeyExchangeModes in the ClientHello, the client must set the 'Recommended' column in the PskKeyExchangeMode registry to 'N' unless a specific mode is explicitly requested."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the ClientHello, the server must verify that the PskKeyExchangeModes are set according to the client's explicit request or have a 'Recommended' value of 'N' otherwise. If not set correctly, the server should ignore the PskKeyExchangeModes extension."
        }
    }
}

