rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "A TLS-compliant client MUST include support for the following digital signature algorithms in the tls.handshake.ciphersuites: rsa_pkcs1_sha256 for certificates, rsa_pss_rsae_sha256 for CertificateVerify and certificates, and ecdsa_secp256r1_sha256 for certificates."
        },
        "processing_rule": {
            "role": "server",
            "content": "A TLS-compliant server MUST verify that the tls.handshake.ciphersuites includes support for rsa_pkcs1_sha256 (for certificates), rsa_pss_rsae_sha256 (for CertificateVerify and certificates), and ecdsa_secp256r1_sha256 (for certificates). If these signature algorithms are not supported, the server MUST abort the handshake with an appropriate 'handshake_failure' or 'insufficient_security' alert."
        }
    }
}

