        "message": "Psk Key Exchange Modes Extension",
        "field": "tls.extension.psk_ke_mode",
        "construction_rule": {
            "role": "client",
            "content": "When sending the ClientHello message, the client MUST include the 'psk_key_exchange_modes' extension in the extensions section. The extension MUST contain the key exchange modes supported by the client, with values defined by IANA."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving a ClientHello with a 'psk_key_exchange_modes' extension, the server MUST verify that the extension is supported and matches the IANA defined values. If the extension is not present or contains unsupported values, the server SHOULD abort the handshake with a suitable alert."
        }
    }
}

