rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "sender",
            "content": "When constructing the cipher_suites field in ClientHello or ServerHello messages, the sender MUST reserve any cipher suite values where the first byte is 255 (decimal) for Private Use, as specified by RFC 8126."
        },
        "processing_rule": {
            "role": "receiver",
            "content": "Upon receiving a cipher_suites list in ClientHello or ServerHello messages, the receiver MUST accept values where the first byte is 255 (decimal) as reserved for Private Use and MUST NOT interpret these values as predefined cipher suites."
        }
    }
}

