rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "Psk Key Exchange Modes Extension",
        "field": "tls.extension.psk_ke_mode",
        "construction_rule": {
            "role": "client",
            "content": "When sending the Psk Key Exchange Modes Extension, the client MUST populate the tls.extension.psk_ke_mode field with one or more key exchange modes, where the initial registry entries psk_ke (value 0) and psk_dhe_ke (value 1) are recommended."
        },
        "processing_rule": {
            "role": "server",
            "content": "Upon receiving the Psk Key Exchange Modes Extension, the server MUST verify that the tls.extension.psk_ke_mode field contains valid key exchange modes and SHOULD give preference to the recommended modes psk_ke (value 0) and psk_dhe_ke (value 1) when selecting a supported mode."
        }
    }
}

