rule:
{
    "structured_rule": {
        "protocol": "TLS 1.3",
        "message": "No Extension",
        "field": "tls.handshake.ciphersuites",
        "construction_rule": {
            "role": "client",
            "content": "When constructing the ClientHello message in TLS 1.3, the client MUST use cipher suite values from the TLS Cipher Suites registry for the tls.handshake.ciphersuites field. Cipher suite values with the first byte in the range 0-254 (decimal) MUST adhere to the 'Specification Required' policy as defined in RFC 8126."
        },
        "processing_rule": {
            "role": "server",
            "content": "When processing the ClientHello message, the server MUST verify that the cipher suite values in the tls.handshake.ciphersuites field comply with the TLS Cipher Suites registry. Cipher suite values with the first byte in the range 0-254 (decimal) MUST conform to the 'Specification Required' policy defined in RFC 8126. If any cipher suite value does not comply, the server MUST reject the ClientHello."
        }
    }
}

strategy:
{
    "rule_violation": "The client includes cipher suite values in the tls.handshake.ciphersuites field that do not comply with the TLS Cipher Suites registry or violate the 'Specification Required' policy defined in RFC 8126.",
    "testing_strategies": [
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with a cipher suite value not in the TLS Cipher Suites registry (e.g., 0xFFFF).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with a cipher suite value containing an invalid first byte in the range 0-254 that does not adhere to the 'Specification Required' policy (e.g., 0x00FF).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with a completely empty tls.handshake.ciphersuites field.",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with a malformed cipher suite (e.g., incorrect length of the tls.handshake.ciphersuites field).",
            "expected_behavior": "Alert"
        },
        {
            "protocol": "TLS 1.3",
            "message": "No Extension",
            "field": "tls.handshake.ciphersuites",
            "description": "Send a ClientHello message with repeated instances of the same invalid cipher suite value in the tls.handshake.ciphersuites field.",
            "expected_behavior": "Alert"
        }
    ]
}

